import React, { useEffect, useMemo, useState } from "react";
import toast from "react-hot-toast";
import PlayerRow from "./PlayerRow";
import MatchHistoryTable from "../../history/components/MatchHistoryTable";
import RecentMatchesStrip from "./RecentMatchesStrip";
import TeamsConfigModal from "./TeamsConfigModal";
import TeamRosterModal from "./TeamRosterModal";
import TeamsSettingsPanel from "./TeamsSettingsPanel";
import { MIN_WAIT_FOR_PRIORITY as WAIT_PRIORITY_MIN } from "../utils/autoQueue";
import { stringToColor } from "../utils/colorHash";
import { normalizeTeamsSettings } from "../../../state/teamSettings";
import { resolvePlayerTeamBadge } from "./TeamBadge";
import { isPlayerPaid, isPlayerUnpaid } from "../../../common/utils/paymentStatus";

export default function PlayerTable({
  players,
  matches,
  currentOpSession,
  onAddPlayer,
  onRemovePlayer,
  onClearAll,
  onSaveSessionAndClear,
  onUpdateLevel,
  onStopPlayer,
  onDepartPlayer,
  onUpdateGender,
  onResumePlayer,
  onUpdatePaymentStatus,
  onMarkArrived,
  onMarkAllPaid,
  onMarkAllArrived,
  onUpdateMemberStatus,
  matchQueue,
  onAddToQueue,
  onRenamePlayer,
  onOpenReclub,
  onUpdateMatch,
  disabled = false,
  duplicateNames = [], // 👈 new prop
  requestedMatches = [], // 👈 new prop
  partners = [], // 👈 new prop for tandem detection
  teamsModeEnabled = false,
  teams = [],
  settings = {},
  setTeamsModeEnabled,
  updateTeamsSettings,
  setTeams,
  assignPlayerToTeam,
  removePlayerFromTeam,
  removeTeam,
}) {
  const [newPlayer, setNewPlayer] = useState("");
  const [newPlayerGender, setNewPlayerGender] = useState("M");
  const [error, setError] = useState("");
  const [sortTick, setSortTick] = useState(0);
  const [activeTab, setActiveTab] = useState("players");
  const [teamsConfigOpen, setTeamsConfigOpen] = useState(false);
  const [teamsSettingsOpen, setTeamsSettingsOpen] = useState(false);
  const [rosterTeam, setRosterTeam] = useState(null);
  const [confirmOpen, setConfirmOpen] = useState(false);
  const [bulkAction, setBulkAction] = useState(null); // 'arrived' | 'paid' | null
  const [searchTerm, setSearchTerm] = useState(""); // 👈 new search state

  useEffect(() => {
    const id = setInterval(() => setSortTick((tick) => tick + 1), 30000);
    return () => clearInterval(id);
  }, []);

  // Toast for duplicates
  const prevDupsRef = React.useRef(0);
  useEffect(() => {
    if (duplicateNames && duplicateNames.length > 0 && duplicateNames.length > prevDupsRef.current) {
      toast.error(`Found ${duplicateNames.length} duplicate name(s)! Highlighted in red.`, {
        duration: 5000,
        position: "top-center",
        id: "duplicate-name-toast", // Static ID to prevent stacking
      });
    }
    prevDupsRef.current = duplicateNames.length;
  }, [duplicateNames]);

  useEffect(() => {
    setSortTick((tick) => tick + 1);
  }, [players]);

  // Compute Recent Match Highlights
  const recentMatchMap = useMemo(() => {
    const map = new Map();
    const now = Date.now();
    const RECENT_THRESHOLD = 15 * 60 * 1000; // 15 mins

    // Matches are not guaranteed to be sorted, so we verify
    const sorted = [...matches].sort((a, b) => (b.endTime || 0) - (a.endTime || 0));

    sorted.forEach(m => {
      if (m.status === 'completed' && m.endTime && (now - m.endTime) < RECENT_THRESHOLD) {
        // Generate color for this match
        const color = stringToColor(m.id || `match-${m.endTime}`);
        // Apply to all players in lineup
        if (m.lineup) {
          m.lineup.forEach(p => {
            if (!map.has(p.id)) {
              map.set(p.id, color);
            }
          });
        }
      }
    });

    return map;
  }, [matches]);

  const teamsSettingsNorm = useMemo(() => normalizeTeamsSettings(settings?.teams), [settings?.teams]);

  const tabs = useMemo(
    () => {
      // Calculate arrived count
      const completedCount = matches.filter(m => m.status === 'completed').length;
      const arrivedCount = players.filter(p => p.arrivalTime > 0).length;

      const base = [
        { id: "players", label: `Players (${arrivedCount}/${players.length})` },
        { id: "payments", label: `Payments (${players.length})` },
        { id: "history", label: `Match History (${completedCount})` },
      ];
      if (teamsModeEnabled) {
        base.splice(3, 0, { id: "teams", label: `Teams (${teams?.length || 0})` });
      }
      return base;
    },
    [players, matches, teamsModeEnabled, teams?.length]
  );

  const handleTeamsToggle = () => {
    if (!setTeamsModeEnabled) return;
    if (!teamsModeEnabled) {
      setTeamsModeEnabled(true);
      if (!(teams || []).length) setTeamsConfigOpen(true);
      toast.success("Teams mode on — configure teams if needed.");
    } else {
      setTeamsModeEnabled(false);
      toast("Teams mode off — open queue restored.", { icon: "ℹ️" });
    }
  };

  useEffect(() => {
    if (!teamsModeEnabled && activeTab === "teams") setActiveTab("players");
  }, [teamsModeEnabled, activeTab]);

  const isQueued = (pid) => matchQueue?.some((item) => item?.playerIds?.includes(pid));

  // Compute partner info map for all players
  const partnerInfoMap = useMemo(() => {
    const map = new Map();
    partners.forEach(p => {
      if (!p.isActive) return;
      const p1 = players.find(x => x.id === p.player1Id);
      const p2 = players.find(x => x.id === p.player2Id);
      if (p1 && p2) {
        map.set(p.player1Id, {
          partnerId: p.player2Id,
          partnerName: p2.name,
          partnerStatus: p2.status,
          isActive: true
        });
        map.set(p.player2Id, {
          partnerId: p.player1Id,
          partnerName: p1.name,
          partnerStatus: p1.status,
          isActive: true
        });
      }
    });
    return map;
  }, [partners, players]);

  const sortedPlayers = useMemo(() => {
    const refreshKey = sortTick;

    const bucket = (player) => {
      if (player.status === "waiting") return 0;
      if (player.status === "queued") return 1;
      if (player.status === "playing") return 2;
      return 3;
    };

    const getWaitMinutes = (player) => {
      if (player.status !== "waiting" && player.status !== "queued") return 0;
      if (!player.waitStart) return 0;
      return Math.floor((Date.now() - player.waitStart) / 60000);
    };

    return [...players].sort((a, b) => {
      const aBucket = bucket(a);
      const bBucket = bucket(b);
      if (aBucket !== bBucket) return aBucket - bBucket;

      if (aBucket === 0 || aBucket === 1) {
        const aWait = getWaitMinutes(a) + refreshKey * 0;
        const bWait = getWaitMinutes(b) + refreshKey * 0;
        const aPriority = aWait >= WAIT_PRIORITY_MIN;
        const bPriority = bWait >= WAIT_PRIORITY_MIN;
        if (aPriority && !bPriority) return -1;
        if (bPriority && !aPriority) return 1;
        if (aPriority && bPriority) return bWait - aWait;
        if (a.matches !== b.matches) return a.matches - b.matches;
        return bWait - aWait;
      }

      if (aBucket === 2) {
        if (a.matches !== b.matches) return a.matches - b.matches;
        return a.name.localeCompare(b.name);
      }

      return a.name.localeCompare(b.name);
    });
  }, [players, sortTick]);

  // Search Filtering
  const displayedPlayers = useMemo(() => {
    if (!searchTerm.trim()) return sortedPlayers;
    const lower = searchTerm.toLowerCase();
    return sortedPlayers.filter(p => p.name.toLowerCase().includes(lower));
  }, [sortedPlayers, searchTerm]);

  const paymentPlayers = useMemo(() => {
    let list = players;
    if (searchTerm.trim()) {
      const lower = searchTerm.toLowerCase();
      list = list.filter(p => p.name.toLowerCase().includes(lower));
    }
    // Default sort for payments? Maybe alphabetical?
    return [...list].sort((a, b) => a.name.localeCompare(b.name));
  }, [players, searchTerm]);


  const filteredMatches = useMemo(() => {
    const sessionStartMs = currentOpSession?.startedAt ?? 0;
    if (!sessionStartMs) return [];

    const sorted = [...matches]
      .filter(m => m.status === 'completed')
      .filter((m) => {
        const stamp = m.endTime || m.startTime || 0;
        return stamp >= sessionStartMs;
      })
      .sort((a, b) => {
        const aTime = a.endTime || a.startTime || 0;
        const bTime = b.endTime || b.startTime || 0;
        return bTime - aTime;
      });
    return sorted;
  }, [matches, currentOpSession?.startedAt]);

  const handleSubmit = (event) => {
    event.preventDefault();
    if (!newPlayer.trim()) return;
    const upperName = newPlayer.trim().toUpperCase();
    if (players.some((p) => p.name.toUpperCase() === upperName)) {
      setError("Player already exists");
      return;
    }
    onAddPlayer(upperName, newPlayerGender, "L.Inter", true /* manualAdd -> auto-arrived */);
    setNewPlayer("");
    setError("");
  };

  // Clear duplicates on rename if it fixes it?
  // Passed down logic could handle it, or we rely on the `duplicateNames` set.
  // When a player is renamed, if their OLD name was in valid list, we might need to re-check?
  // Actually, `importReclubParticipants` return value sets the `duplicateNames` state.
  // If user renames one of them, we rely on the parent (QueuePage) or we can clear specific name.
  // For simplicity, if we rename, we can remove that name from duplicates list.
  const handleRenameProxy = (id, newName) => {
    onRenamePlayer(id, newName);
  };


  return (
    <div className={`shadow-none rounded-xl p-0 h-full flex flex-col min-h-0 relative bg-transparent`}>
      <div className="flex items-center justify-between mb-3">
        <div className="flex items-center gap-2 p-1 bg-slate-100 rounded-lg">
          {tabs.map((tab) => (
            <button
              key={tab.id}
              type="button"
              className={`px-3 py-1.5 text-xs font-semibold rounded-md transition-all ${activeTab === tab.id
                ? "bg-pt-teal text-white shadow-sm"
                : "text-slate-500 hover:text-pt-teal hover:bg-slate-200"
                }`}
              onClick={() => {
                setActiveTab(tab.id);
                setSearchTerm(""); // Clear search on tab switch
              }}
            >
              {tab.label}
            </button>
          ))}
        </div>

        {activeTab === "players" && (
          <div className="flex items-center gap-2 flex-wrap justify-end">
            <button
              type="button"
              onClick={() => setConfirmOpen(true)}
              className="border border-red-200 text-red-600 px-3 py-1 text-xs rounded-full hover:bg-red-50 hover:border-red-300 transition-colors"
            >
              Clear All
            </button>
            <label className="flex items-center gap-1.5 text-xs font-semibold text-slate-700 cursor-pointer border border-slate-200 rounded-full px-3 py-1 hover:bg-slate-50">
              <input
                type="checkbox"
                className="accent-pt-teal"
                checked={!!teamsModeEnabled}
                onChange={handleTeamsToggle}
                disabled={disabled}
              />
              Teams
            </label>
            <button
              type="button"
              title="Re-sort list"
              onClick={() => setSortTick((tick) => tick + 1)}
              className="text-xs px-2 py-1 border border-slate-200 text-slate-500 rounded-full hover:bg-slate-50"
            >
              ↻
            </button>
          </div>
        )}
        {activeTab === "teams" && teamsModeEnabled && (
          <div className="flex items-center gap-2">
            <button
              type="button"
              className="text-xs px-3 py-1 rounded-full border border-pt-teal text-pt-teal font-semibold hover:bg-pt-teal/5"
              onClick={() => setTeamsSettingsOpen(true)}
            >
              Team Settings
            </button>
            <button
              type="button"
              className="text-xs px-3 py-1 rounded-full border border-slate-200 text-slate-600 hover:bg-slate-50"
              onClick={() => setTeamsConfigOpen(true)}
            >
              Edit teams
            </button>
          </div>
        )}
      </div>

      {activeTab === "players" ? (
        <>
          <div className="mb-4 space-y-2">
            {/* Search Bar */}
            <div className="relative">
              <input
                type="text"
                placeholder="🔍 Search players..."
                className="w-full border border-slate-200 rounded-lg px-3 py-2 text-sm focus:ring-2 focus:ring-pt-teal/20 focus:border-pt-teal outline-none"
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
              />
            </div>

            <form onSubmit={handleSubmit} className="flex flex-wrap gap-2 items-start">
              <div className="flex flex-col flex-1 min-w-[200px]">
                <input
                  type="text"
                  value={newPlayer}
                  onChange={(e) => {
                    setNewPlayer(e.target.value);
                    if (error) setError("");
                  }}
                  placeholder="Enter player name"
                  className={`border rounded-lg p-2 text-sm focus:ring-2 focus:ring-pt-teal/20 focus:border-pt-teal outline-none transition-all ${error ? "border-red-500" : "border-slate-200"
                    }`}
                />
                {error && <span className="text-red-500 text-xs mt-1">{error}</span>}
              </div>

              {/* Gender Slider Toggle */}
              <div className="flex items-center border border-slate-200 rounded-lg overflow-hidden text-sm font-medium">
                <button
                  type="button"
                  onClick={() => setNewPlayerGender("M")}
                  className={`px-3 py-2 transition-colors ${newPlayerGender === "M"
                    ? "bg-blue-500 text-white"
                    : "bg-white text-slate-500 hover:bg-slate-50"
                    }`}
                >
                  M
                </button>
                <button
                  type="button"
                  onClick={() => setNewPlayerGender("F")}
                  className={`px-3 py-2 transition-colors ${newPlayerGender === "F"
                    ? "bg-pink-500 text-white"
                    : "bg-white text-slate-500 hover:bg-slate-50"
                    }`}
                >
                  F
                </button>
              </div>

              <button
                type="submit"
                className="bg-pt-teal text-white px-4 py-2 rounded-lg hover:bg-pt-teal/90 text-sm font-medium transition-colors shadow-sm"
              >
                + Add
              </button>
              <button
                type="button"
                onClick={() => onOpenReclub?.()}
                // Use pt-orange for secondary heavy actions or external integrations
                className="bg-pt-orange text-white px-4 py-2 rounded-lg hover:bg-[#8a723e] text-sm font-medium transition-colors shadow-sm"
              >
                Reclub Meet
              </button>
            </form>
          </div>

          <div className="flex-1 min-h-0 overflow-y-auto rounded-lg border border-pt-teal/10">
            <table className="w-full text-sm">
              <thead className="sticky top-0 z-10 bg-pt-teal/5 backdrop-blur-sm">
                <tr>
                  <th className="p-3 text-center text-xs font-bold text-pt-teal/40 uppercase tracking-wider w-8">#</th>
                  <th className="p-3 text-left text-xs font-bold text-pt-teal uppercase tracking-wider">Name</th>
                  <th className="p-3 text-xs font-bold text-pt-teal uppercase tracking-wider">Reclub ID</th>
                  <th className="p-3 text-xs font-bold text-pt-teal uppercase tracking-wider">Level</th>
                  <th className="p-3 text-xs font-bold text-pt-teal uppercase tracking-wider">Gender</th>
                  <th className="p-3 text-xs font-bold text-pt-teal uppercase tracking-wider">Status</th>
                  <th className="p-3 text-xs font-bold text-pt-teal uppercase tracking-wider">Wait</th>
                  <th className="p-3 text-xs font-bold text-pt-teal uppercase tracking-wider">Matches</th>
                  <th className="p-3 text-center text-xs font-bold text-pt-teal uppercase tracking-wider">Action</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-gray-100 bg-white">
                {displayedPlayers.map((player, idx) => {
                  const isDup = duplicateNames.includes(player.name.toUpperCase());
                  const isReq = (requestedMatches || []).some(m => m.playerIds.includes(player.id));
                  const tb = resolvePlayerTeamBadge(
                    player,
                    teams || [],
                    teamsModeEnabled,
                    teamsSettingsNorm.unassignedLabel
                  );
                  return (
                    <PlayerRow
                      key={player.id}
                      rowNumber={idx + 1}
                      player={player}
                      queued={isQueued(player.id)}
                      onRemovePlayer={onRemovePlayer}
                      onUpdateLevel={onUpdateLevel}
                      onUpdateGender={onUpdateGender}
                      onUpdatePaymentStatus={onUpdatePaymentStatus}
                      onStopPlayer={onStopPlayer}
                      onDepartPlayer={onDepartPlayer}
                      onResumePlayer={onResumePlayer}
                      onAddToQueue={onAddToQueue}
                      onRenamePlayer={handleRenameProxy}
                      isDuplicate={isDup}
                      isRequested={isReq}
                      partnerInfo={partnerInfoMap.get(player.id)}
                      recentMatchColor={recentMatchMap.get(player.id)}
                      teamBadge={tb || undefined}
                    />
                  );
                })}
              </tbody>
            </table>
          </div>

          <RecentMatchesStrip matches={matches} onUpdateMatch={onUpdateMatch} />

          {confirmOpen && (
            <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/30 backdrop-blur-sm">
              <div className="bg-white rounded-xl shadow-xl max-w-md w-full mx-4 p-6 border border-pt-teal/10">
                <h2 className="text-lg font-display text-pt-teal mb-2">Clear all players?</h2>
                <p className="text-xs text-slate-600 mb-4">
                  Are you sure you want to clear all the players from the list? You will not be able
                  to save the details from this session unless you save it now.
                </p>
                <div className="flex flex-col sm:flex-row gap-2 justify-end">
                  <button
                    type="button"
                    onClick={() => {
                      onSaveSessionAndClear?.();
                      setConfirmOpen(false);
                    }}
                    className="bg-pt-teal text-white px-4 py-2 text-xs font-medium rounded-full hover:bg-pt-teal/90"
                  >
                    Save Session and Clear
                  </button>
                  <button
                    type="button"
                    onClick={() => {
                      onClearAll();
                      setConfirmOpen(false);
                    }}
                    className="border border-red-200 text-red-600 px-4 py-2 text-xs font-medium rounded-full hover:bg-red-50"
                  >
                    Clear Players
                  </button>
                  <button
                    type="button"
                    onClick={() => setConfirmOpen(false)}
                    className="text-xs px-4 py-2 rounded-full text-slate-500 hover:bg-slate-100"
                  >
                    Cancel
                  </button>
                </div>
              </div>
            </div>
          )}
        </>
      ) : activeTab === "payments" ? (
        <div className="flex-1 min-h-0 overflow-y-auto rounded-lg border border-pt-teal/10 flex flex-col">
          {/* Bulk Actions Header */}
          <div className="p-2 border-b border-pt-teal/10 flex items-center justify-between gap-2 bg-slate-50">
            <div className="flex items-center gap-3">
              <input
                type="text"
                placeholder="🔍 Search payments..."
                className="border border-slate-200 rounded-lg px-2 py-1 text-xs focus:ring-1 focus:ring-pt-teal/20 focus:border-pt-teal outline-none min-w-[150px]"
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
              />
              <div className="flex gap-2 text-[10px] font-mono border-l pl-2 border-slate-200">
                <span className="bg-emerald-50 text-emerald-700 px-1.5 py-0.5 rounded border border-emerald-100">
                  Arrived: {players.filter(p => p.arrivalTime > 0).length}
                </span>
                <span className="bg-pt-teal/10 text-pt-teal px-1.5 py-0.5 rounded border border-pt-teal/20">
                  Paid: {players.filter((p) => isPlayerPaid(p.paymentStatus, p.paymentMethod)).length}
                </span>
              </div>
            </div>
            <div className="flex gap-2">
              <button
                type="button"
                onClick={() => setBulkAction('arrived')}
                className="text-xs px-3 py-1.5 rounded-md bg-emerald-100 text-emerald-700 hover:bg-emerald-200 font-medium transition-colors"
              >
                All Arrived
              </button>
              <button
                type="button"
                onClick={() => setBulkAction('paid')}
                className="text-xs px-3 py-1.5 rounded-md bg-pt-teal text-white hover:bg-pt-teal/90 font-medium transition-colors shadow-sm"
              >
                All Paid
              </button>
            </div>
          </div>
          <table className="w-full text-sm">
            <thead className="sticky top-0 z-10 bg-pt-teal/5 backdrop-blur-sm">
              <tr>
                <th className="p-3 text-left text-xs font-bold text-pt-teal uppercase tracking-wider">Name</th>
                <th className="p-3 text-center text-xs font-bold text-pt-teal uppercase tracking-wider">Payment</th>
                <th className="p-3 text-center text-xs font-bold text-pt-teal uppercase tracking-wider">Arrival</th>
                <th className="p-3 text-center text-xs font-bold text-pt-teal uppercase tracking-wider">Departure</th>
                <th className="p-3 text-center text-xs font-bold text-pt-teal uppercase tracking-wider">Action</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-100 bg-white">
              {paymentPlayers.map((player) => (
                <tr key={player.id} className="hover:bg-pt-teal/5 transition-colors">
                  <td className="p-3 text-left font-medium text-slate-700">{player.name}</td>
                  <td className="p-3 text-center">
                    <div className="flex flex-col items-center gap-2">
                      {/* Status Buttons */}
                      <div className="flex items-center bg-slate-100 rounded-lg p-0.5">
                        <button
                          type="button"
                          onClick={() => onUpdatePaymentStatus(player.id, "unpaid", null)}
                          className={`px-3 py-1 text-xs font-medium rounded-md transition-all ${isPlayerUnpaid(player.paymentStatus, player.paymentMethod)
                            ? "bg-white text-rose-600 shadow-sm"
                            : "text-slate-400 hover:text-slate-600"
                            }`}
                        >
                          Unpaid
                        </button>
                        <button
                          type="button"
                          onClick={() => onUpdatePaymentStatus(player.id, "paid", player.paymentMethod === "free" ? "cash" : (player.paymentMethod || "cash"))}
                          className={`px-3 py-1 text-xs font-medium rounded-md transition-all ${isPlayerPaid(player.paymentStatus, player.paymentMethod)
                            ? "bg-pt-teal text-white shadow-sm"
                            : "text-slate-400 hover:text-slate-600"
                            }`}
                        >
                          Paid
                        </button>
                      </div>

                      {/* MOP Select */}
                      <select
                        value={player.paymentMethod || ""}
                        onChange={(e) => {
                          const method = e.target.value;
                          if (method === "free") {
                            onUpdatePaymentStatus(player.id, "free", "free");
                          } else if (isPlayerPaid(player.paymentStatus, player.paymentMethod)) {
                            onUpdatePaymentStatus(player.id, "paid", method);
                          } else {
                            onUpdatePaymentStatus(player.id, "unpaid", method);
                          }
                        }}
                        className="border border-slate-200 rounded-lg px-2 py-1 text-xs bg-white w-full max-w-[120px] focus:border-pt-teal outline-none"
                      >
                        <option value="" disabled>Select MOP</option>
                        <option value="cash">Cash</option>
                        <option value="gcash">GCash</option>
                        <option value="gotyme">GoTyme</option>
                        <option value="bank">Bank</option>
                        <option value="free">Free</option>
                      </select>
                      <label className="inline-flex items-center gap-1.5 text-[11px] text-slate-600">
                        <input
                          type="checkbox"
                          checked={!!player.isMember}
                          onChange={(e) => onUpdateMemberStatus?.(player.id, e.target.checked)}
                          className="accent-pt-teal"
                        />
                        Member
                      </label>
                      <span className="text-[11px] font-semibold text-pt-teal">
                        ₱{Number(player.price || 0).toLocaleString()}
                      </span>
                    </div>
                  </td>
                  <td className="p-3 text-center text-xs text-slate-500 font-mono">
                    {player.arrivalTime
                      ? new Date(player.arrivalTime).toLocaleTimeString([], {
                        hour: "2-digit",
                        minute: "2-digit",
                      })
                      : "—"}
                  </td>
                  {/* Departure Time */}
                  <td className="p-3 text-center text-xs text-slate-400 font-mono">
                    {player.departureTime
                      ? new Date(player.departureTime).toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" })
                      : <span className="text-slate-200">—</span>}
                  </td>
                  {/* Action column */}
                  <td className="p-3 text-center">
                    <div className="flex flex-col items-center gap-1">
                      {/* Tag Arrived: show for any player without arrivalTime who hasn't departed */}
                      {!player.arrivalTime && player.status !== 'departed' && (
                        <button
                          type="button"
                          className="text-xs px-3 py-1 rounded-full bg-emerald-600 text-white hover:bg-emerald-700 shadow-sm"
                          onClick={() => onMarkArrived(player.id)}
                        >
                          Tag Arrived
                        </button>
                      )}
                      {/* Depart: show for players who have arrived but haven't departed */}
                      {player.arrivalTime && !player.departureTime && onDepartPlayer && (
                        <button
                          type="button"
                          className="text-xs px-3 py-1 rounded-full bg-red-100 text-red-600 hover:bg-red-200 font-medium"
                          onClick={() => onDepartPlayer(player.id)}
                        >
                          &#9209; Depart
                        </button>
                      )}
                      {/* Already departed */}
                      {player.status === 'departed' && (
                        <span className="text-xs text-slate-400 italic">Departed</span>
                      )}
                      {/* No action needed: arrived and still active */}
                      {player.arrivalTime && !player.departureTime && player.status !== 'departed' && !onDepartPlayer && (
                        <span className="text-xs text-slate-300 italic">—</span>
                      )}
                    </div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      ) : activeTab === "teams" && teamsModeEnabled ? (
        <div className="flex-1 min-h-0 overflow-y-auto rounded-lg border border-pt-teal/10 p-3">
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
            {(teams || []).map((team) => {
              const memberCount = players.filter((p) => p.teamId != null && String(p.teamId) === String(team.id)).length;
              return (
                <button
                  key={team.id}
                  type="button"
                  className="text-left rounded-xl border border-slate-200 p-4 hover:border-pt-teal/40 hover:bg-pt-teal/5 transition-colors"
                  onClick={() => setRosterTeam(team)}
                >
                  <div className="flex items-center gap-3">
                    <span
                      className="w-12 h-12 rounded-xl shrink-0 shadow-inner border border-white/50"
                      style={{ backgroundColor: team.color }}
                    />
                    <div>
                      <div className="font-display font-bold text-slate-900">{team.name}</div>
                      <div className="text-[11px] text-slate-500">
                        {memberCount} player{memberCount === 1 ? "" : "s"}
                      </div>
                    </div>
                  </div>
                </button>
              );
            })}
            <div className="rounded-xl border border-dashed border-slate-200 p-4 bg-slate-50/80">
              <div className="font-semibold text-slate-700">{teamsSettingsNorm.unassignedLabel || "Unassigned"}</div>
              <div className="text-[11px] text-slate-500 mt-1">
                {players.filter((p) => !p.teamId).length} player(s) not on a team
              </div>
            </div>
          </div>
        </div>
      ) : (
        <div className="flex-1 min-h-0 overflow-hidden flex flex-col">
          <div className="flex items-center justify-between mb-3">
            <h3 className="text-base font-semibold text-pt-teal">Match History</h3>
            <span className="text-xs text-slate-500">Current session only</span>
          </div>

          <div className="flex-1 min-h-0 overflow-y-auto border border-pt-teal/10 rounded-lg">
            <MatchHistoryTable matches={filteredMatches} onUpdateMatch={onUpdateMatch} />
          </div>
        </div>
      )}
      {/* Confirmation Modal Logic */}
      {bulkAction && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/30 backdrop-blur-sm animate-in fade-in duration-200">
          <div className="bg-white rounded-xl shadow-xl max-w-sm w-full mx-4 p-6 border border-pt-teal/10">
            <h2 className="text-lg font-display text-pt-teal mb-2">
              {bulkAction === 'arrived' ? "Mark all as Arrived?" : "Mark all as Paid?"}
            </h2>
            <p className="text-xs text-slate-600 mb-6">
              {bulkAction === 'arrived'
                ? "This will set the status of all stopped players to 'Waiting' and update their arrival time to now. Players currently in matches or queued will be unaffected."
                : "This will mark all Unpaid players as Paid via Cash. Players with existing payment methods will not be changed."}
            </p>
            <div className="flex justify-end gap-2">
              <button
                onClick={() => setBulkAction(null)}
                className="px-4 py-2 rounded-full text-slate-500 hover:bg-slate-100 text-xs font-medium"
              >
                Cancel
              </button>
              <button
                onClick={() => {
                  if (bulkAction === 'arrived') onMarkAllArrived();
                  else if (bulkAction === 'paid') onMarkAllPaid();
                  setBulkAction(null);
                }}
                className="bg-pt-teal text-white px-4 py-2 rounded-full hover:bg-pt-teal/90 text-xs font-medium shadow-sm transition-transform active:scale-95"
              >
                Confirm
              </button>
            </div>
          </div>
        </div>
      )}

      <TeamsConfigModal
        isOpen={teamsConfigOpen}
        onClose={() => setTeamsConfigOpen(false)}
        initialTeams={teams || []}
        teamsSettings={teamsSettingsNorm}
        onTeamsSettingsChange={(patch) => updateTeamsSettings?.(patch)}
        onSave={(draft) => {
          setTeams?.(draft);
          setTeamsConfigOpen(false);
          toast.success("Teams saved");
        }}
      />

      <TeamRosterModal
        isOpen={!!rosterTeam}
        onClose={() => setRosterTeam(null)}
        team={rosterTeam}
        players={players}
        unassignedLabel={teamsSettingsNorm.unassignedLabel}
        onAssignPlayer={(playerId, tid) => assignPlayerToTeam?.(playerId, tid)}
        onRemovePlayer={(playerId) => {
          const ok = removePlayerFromTeam?.(playerId);
          if (ok === false) {
            toast.error("Can't remove team assignment while the player is on court.");
          }
        }}
      />

      {teamsSettingsOpen && (
        <div className="fixed inset-0 z-[95] flex items-center justify-center bg-black/40 backdrop-blur-sm p-4">
          <div className="bg-white rounded-2xl shadow-xl max-w-md w-full max-h-[90vh] overflow-y-auto p-6 border border-slate-200">
            <div className="flex justify-between items-center mb-4">
              <h2 className="text-lg font-display font-semibold text-slate-900">Team Settings</h2>
              <button type="button" className="text-slate-400 hover:text-slate-700 text-xl" onClick={() => setTeamsSettingsOpen(false)}>
                ×
              </button>
            </div>
            <TeamsSettingsPanel
              teamsSettings={teamsSettingsNorm}
              onChange={(patch) => updateTeamsSettings?.(patch)}
              idPrefix="panel"
            />
            <div className="mt-6 flex justify-end">
              <button
                type="button"
                className="px-4 py-2 rounded-full bg-pt-teal text-white text-xs font-semibold"
                onClick={() => setTeamsSettingsOpen(false)}
              >
                Done
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}
