import React, { useEffect, useState, useMemo, useRef } from "react";
import { reclubService } from "../../../services";
import ConfirmationModal from "../../../common/components/ConfirmationModal";
import { formatReclubIdLabel, reclubIdentityFromParticipant } from "../utils/reclubPlayer";

export default function ReclubModal({ open, onClose, onImportParticipants }) {
  // Keep hooks stable even when closed
  useEffect(() => {
    const onKey = (e) => {
      if (e.key === "Escape" && !confirmImportRef.current) onClose?.();
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [onClose]);

  const [meetCode, setMeetCode] = useState("");
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);
  const [profileWarning, setProfileWarning] = useState(null);
  const [composed, setComposed] = useState(null);
  const [confirmImport, setConfirmImport] = useState(false);
  const confirmImportRef = useRef(false);
  confirmImportRef.current = confirmImport;

  useEffect(() => {
    if (!open) {
      // Reset state when closing
      setMeetCode("");
      setLoading(false);
      setError(null);
      setProfileWarning(null);
      setComposed(null);
      setConfirmImport(false);
    }
  }, [open]);

  const disabled = useMemo(() => loading || !meetCode.trim(), [loading, meetCode]);

  const handleFetch = async () => {
    setLoading(true);
    setError(null);
    setProfileWarning(null);
    setComposed(null);
    setConfirmImport(false);
    try {
      const data = await reclubService.getMeetByRef(meetCode.trim());

      // While loading, gather participant list and enrich via Players API
      const rawParts = Array.isArray(data?.participants) ? data.participants : [];
      const activeNonHosts = rawParts.filter((p) => p?.status === 1 && !p?.isHost);

      // Only gather real user IDs for lookup (exclude +1/guests: referenceType === 3)
      const ids = activeNonHosts
        .filter((p) => p?.referenceType !== 3)
        .map((p) => p?.referenceId)
        .filter((id) => id !== undefined && id !== null);
      const uniqueIds = [...new Set(ids)];

      let playersMap = new Map();
      if (uniqueIds.length > 0) {
        try {
          const res = await reclubService.getPlayersByUserIds(uniqueIds);
          const list = Array.isArray(res?.players) ? res.players : [];
          playersMap = new Map(list.map((pl) => [pl.userId, pl]));
        } catch (e) {
          setProfileWarning(
            "Player profiles could not be loaded. Names and photos may be incomplete. You can still import this meet."
          );
        }
      }

      const formatName = (full) => {
        if (!full || typeof full !== "string") return "";
        const parts = full.trim().split(/\s+/);
        if (parts.length >= 2) {
          return `${parts[0]} ${parts[1].charAt(0).toUpperCase()}.`;
        }
        return parts[0];
      };

      const compiled = activeNonHosts.map((p) => {
        const isPlusOne = p?.referenceType === 3;
        const byId = !isPlusOne && p.referenceId ? playersMap.get(p.referenceId) : null;
        const baseName = isPlusOne
          ? (p?.externalReference?.name || "")
          : (byId?.name || p?.externalReference?.name || "");
        const name = formatName(baseName);
        const gender = (byId?.gender || "M") || "M";
        // For +1/guest, there is no image: use default/fallback symbol by leaving null
        const imageUrl = isPlusOne ? null : (byId?.imageUrl || null);
        const identity = reclubIdentityFromParticipant({
          referenceId: p.referenceId,
          referenceType: p.referenceType,
        });
        return {
          referenceId: identity.referenceId,
          referenceType: identity.referenceType,
          isGuest: identity.isGuest,
          reclubUserId: identity.reclubUserId,
          name,
          gender,
          imageUrl,
          status: p.status,
          isHost: p.isHost,
          tags: p.tags || [],
        };
      });
      // Build single combined response: meet name + participants
      const combined = {
        name: data?.name || "",
        referenceCode: data?.referenceCode || meetCode.trim(),
        participants: compiled,
      };
      setComposed(combined);
    } catch (err) {
      const msg = err?.data?.message || err?.message || "Failed to fetch meet";
      setError(msg);
    } finally {
      setLoading(false);
    }
  };

  if (!open) return null;

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center">
      {/* Backdrop */}
      <div className="absolute inset-0 bg-black/40" onClick={onClose} />

      {/* Modal Card */}
      <div className="relative bg-white rounded-xl shadow-3xl w-[min(98vw,880px)] p-6 animate-[fadeIn_120ms_ease-out]">
        <div className="flex items-start justify-between mb-4">
          <h2 className="text-xl font-bold text-[#1E3A8A]">Reclub Meet Lookup</h2>
          <button
            onClick={onClose}
            className="text-gray-500 hover:text-gray-700"
            aria-label="Close"
          >
            ✕
          </button>
        </div>

        <div className="space-y-3">
          <label className="block text-sm font-medium text-gray-700">
            Meet Code
          </label>
          <div className="flex gap-2">
            <input
              type="text"
              value={meetCode}
              onChange={(e) => setMeetCode(e.target.value.toUpperCase())}
              placeholder="e.g. GB7NMN"
              className="flex-1 border rounded px-3 py-2 text-sm"
            />
            <button
              onClick={handleFetch}
              disabled={disabled}
              className={`px-4 py-2 rounded text-white text-sm ${disabled ? "bg-gray-400" : "bg-[#1E3A8A] hover:bg-[#243c90]"}`}
            >
              {loading ? "Fetching…" : "Fetch"}
            </button>
          </div>
          <p className="text-xs text-gray-500">
            Uses configured Reclub credentials or shared defaults to authenticate.
          </p>
        </div>

        <div className="mt-5 space-y-3">
          {error && (
            <div className="bg-red-50 border border-red-200 text-red-700 rounded p-3 text-sm">
              {String(error)}
            </div>
          )}

          {profileWarning && (
            <div className="bg-amber-50 border border-amber-300 text-amber-900 rounded p-3 text-sm" role="alert">
              {profileWarning}
            </div>
          )}

          {composed && (
            <div>
              <h3 className="text-sm font-semibold text-gray-700 mb-1">
                {composed.name || "Meet"}{" "}
                <span className="font-normal text-gray-500">({composed.referenceCode})</span>
              </h3>
              <p className="text-xs text-gray-500 mb-2">
                {composed.participants.length} participant{composed.participants.length === 1 ? "" : "s"} ready to import.
              </p>
              <div className="overflow-auto max-h-[50vh] border rounded">
                <table className="w-full text-sm">
                  <thead className="bg-slate-50 sticky top-0">
                    <tr>
                      <th className="p-2 text-left text-xs font-semibold text-slate-600">Name</th>
                      <th className="p-2 text-left text-xs font-semibold text-slate-600">Reclub ID</th>
                      <th className="p-2 text-left text-xs font-semibold text-slate-600">Gender</th>
                    </tr>
                  </thead>
                  <tbody>
                    {composed.participants.length === 0 ? (
                      <tr>
                        <td colSpan={3} className="p-3 text-sm text-slate-500">
                          No active participants to import.
                        </td>
                      </tr>
                    ) : (
                      composed.participants.map((participant, index) => (
                        <tr key={`${participant.referenceId ?? "row"}-${index}`} className="border-t">
                          <td className="p-2">{participant.name || "—"}</td>
                          <td className="p-2 tabular-nums">{formatReclubIdLabel(participant)}</td>
                          <td className="p-2">{participant.gender || ""}</td>
                        </tr>
                      ))
                    )}
                  </tbody>
                </table>
              </div>
            </div>
          )}
        </div>

        <div className="mt-6 flex justify-end gap-2">
          <button
            onClick={() => {
              if (!composed || loading) return;
              if ((composed.participants || []).length === 0) {
                onImportParticipants?.(composed);
                return;
              }
              setConfirmImport(true);
            }}
            disabled={!composed || loading}
            className={`px-3 py-2 rounded text-sm text-white ${(!composed || loading) ? "bg-gray-400" : "bg-[#065F46] hover:bg-[#0b7a58]"}`}
          >
            Import
          </button>
          <button onClick={onClose} className="px-3 py-2 rounded border text-sm hover:bg-gray-50">Close</button>
        </div>
      </div>

      <ConfirmationModal
        isOpen={confirmImport}
        isDestructive
        title="Replace the current roster?"
        message="Import replaces the player roster and clears courts, the queue, and matches. This cannot be undone from this screen."
        confirmLabel="Import and replace"
        cancelLabel="Cancel"
        onCancel={() => setConfirmImport(false)}
        onConfirm={() => {
          setConfirmImport(false);
          if (composed) onImportParticipants?.(composed);
        }}
      />
    </div>
  );
}
