// Canonical rental promo calculator. Production clients consume server quotes.
const DEFAULT_RENTAL_PROMO = Object.freeze({
  schemaVersion: 1, id: 'south-dinkers-october-2026', enabled: false,
  startDate: '2026-10-12', endDate: '2026-10-31', weekdays: [1, 2, 3, 4],
  startMinute: 480, endMinute: 1020, blockHours: 2,
  blockPrice: 600, singleHourPrice: 400, application: 'eligible-hours', aggregation: 'booking-court-hours',
});

const manilaDate = (now = new Date()) => new Intl.DateTimeFormat('en-CA', {
  timeZone: 'Asia/Manila', year: 'numeric', month: '2-digit', day: '2-digit',
}).format(now);

const validDate = (date) => typeof date === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(date)
  && !Number.isNaN(Date.parse(`${date}T00:00:00Z`))
  && new Date(`${date}T00:00:00Z`).toISOString().slice(0, 10) === date;

const validateRentalPromo = (promo) => {
  if (promo == null) return null;
  if (typeof promo !== 'object' || Array.isArray(promo) || typeof promo.enabled !== 'boolean') return 'Invalid rental promo.';
  if (promo.startDate != null && promo.startDate !== '' && !validDate(promo.startDate)) return 'Enter a valid promo start date.';
  if (!validDate(promo.endDate)) return 'Enter a valid promo end date.';
  if (promo.enabled && !validDate(promo.startDate)) return 'Set a start date before enabling the promo.';
  if (promo.startDate && promo.startDate > promo.endDate) return 'Promo end date must be on or after its start date.';
  if (![undefined, 'eligible-hours', 'eligible-contiguous-hours', 'whole-period'].includes(promo.application)) return 'Invalid promo time-window rule.';
  const resolved = { ...DEFAULT_RENTAL_PROMO, ...promo };
  if (typeof resolved.id !== 'string' || !resolved.id.trim()) return 'Enter a valid promo identifier.';
  if (!Array.isArray(resolved.weekdays) || !resolved.weekdays.length
    || resolved.weekdays.some(day => !Number.isInteger(day) || day < 0 || day > 6)
    || new Set(resolved.weekdays).size !== resolved.weekdays.length) return 'Select at least one valid weekday without duplicates.';
  if (![resolved.startMinute, resolved.endMinute].every(minute => Number.isInteger(minute) && minute >= 0 && minute <= 1440 && minute % 60 === 0)
    || resolved.startMinute >= resolved.endMinute) return 'Choose whole-hour start and end times, with the end after the start.';
  if (resolved.blockHours !== 2) return 'Promo packages must contain two court-hours.';
  const isMoney = value => typeof value === 'number' && Number.isFinite(value) && value >= 0
    && Number.isSafeInteger(Math.round(value * 100)) && Math.abs(value * 100 - Math.round(value * 100)) < 0.000001;
  if (!isMoney(resolved.singleHourPrice) || !isMoney(resolved.blockPrice)) return 'Enter valid non-negative prices with up to two decimal places.';
  if (resolved.blockPrice < resolved.singleHourPrice || resolved.blockPrice > resolved.singleHourPrice * 2) return 'The two-hour price must be between the one-hour price and twice that price.';
  return null;
};

const resolveRentalPromo = (value) => ({ ...DEFAULT_RENTAL_PROMO, ...value,
  application: value?.application === 'eligible-contiguous-hours' ? 'eligible-hours' : (value?.application || DEFAULT_RENTAL_PROMO.application),
  aggregation: 'booking-court-hours',
  // Missing fields retain the original campaign's backward-compatible defaults.
  weekdays: [...(Array.isArray(value?.weekdays) ? value.weekdays : DEFAULT_RENTAL_PROMO.weekdays)],
});

const rentalPromoStatus = (value, now = new Date()) => {
  if (!value?.enabled || validateRentalPromo(value)) return 'disabled';
  const today = manilaDate(now);
  if (today < value.startDate) return 'scheduled';
  if (today > value.endDate) return 'expired';
  return 'active';
};

export { DEFAULT_RENTAL_PROMO, manilaDate, validateRentalPromo, resolveRentalPromo, rentalPromoStatus };
