import { commitOp, readDeviceRecord } from "./entityStore";
import { isDisplaySurface, getVoicePrefsSync, rememberVoicePrefs } from "./storage";
import { isLeaderboardSurface } from "./e2eMode";

const VOICE_DEFAULTS = { voiceName: "", rate: 0.9, pitch: 1 };

let cache = null;
let durableVoice = null;
let saveTail = Promise.resolve();
let pendingSaves = 0;
let selectionVersion = 0;
let saveGeneration = 0;
const listeners = new Set();

function normalizeVoice(voice = {}) {
  return {
    voiceName: voice.voiceName || "",
    rate: Number(voice.rate ?? VOICE_DEFAULTS.rate),
    pitch: Number(voice.pitch ?? VOICE_DEFAULTS.pitch),
  };
}

function publishVoice(voice) {
  cache = voice;
  rememberVoicePrefs(voice);
  emit();
}

export function getVoiceSync() {
  if (cache) return cache;
  const fromIdb = getVoicePrefsSync();
  return {
    voiceName: fromIdb.voiceName || VOICE_DEFAULTS.voiceName,
    rate: Number(fromIdb.rate ?? VOICE_DEFAULTS.rate),
    pitch: Number(fromIdb.pitch ?? VOICE_DEFAULTS.pitch),
  };
}

function emit() {
  const snap = getVoiceSync();
  listeners.forEach((listener) => listener(snap));
}

export function subscribeVoice(listener) {
  listeners.add(listener);
  return () => listeners.delete(listener);
}

export async function hydrateVoiceSettings() {
  if (pendingSaves) return getVoiceSync();
  const version = selectionVersion;
  const row = await readDeviceRecord("voice");
  // A delayed read or an echo from our previous commit must not replace a
  // newer local slider/selector value that is waiting in the save lane.
  if (pendingSaves || version !== selectionVersion) return getVoiceSync();
  if (row?.data) {
    durableVoice = normalizeVoice(row.data);
    publishVoice(durableVoice);
    return cache;
  }
  cache = getVoiceSync();
  rememberVoicePrefs(cache);
  return cache;
}

export async function saveVoiceSettings(next) {
  const previous = getVoiceSync();
  const voice = normalizeVoice(next);
  const generation = saveGeneration;
  selectionVersion += 1;
  publishVoice(voice);
  if (isDisplaySurface() || isLeaderboardSurface()) return voice;
  pendingSaves += 1;
  // Each local selection reads its baseline after the prior local write has
  // finished. Other tabs still participate through normal rev conflicts.
  const saving = saveTail.then(async () => {
    if (generation !== saveGeneration) throw new Error("Voice settings changed in another window. Review the current selection and try again.");
    let restored = durableVoice || previous;
    try {
      const existing = await readDeviceRecord("voice");
      if (existing?.data) {
        durableVoice = normalizeVoice(existing.data);
        restored = durableVoice;
      }
      if (existing?.data
        && (existing.data.voiceName || "") === voice.voiceName
        && Number(existing.data.rate) === voice.rate
        && Number(existing.data.pitch) === voice.pitch) {
        return voice;
      }
      const result = await commitOp({
        opId: `voice:${Date.now()}:${Math.random().toString(36).slice(2, 6)}`,
        actorId: "voice",
        writes: [{
          kind: "device",
          id: "voice",
          baseRev: existing?.rev || 0,
          base: existing?.data || null,
          next: voice,
        }],
        tombstones: [],
      }, { writer: "staff" });
      if (result?.ok || result?.reason === "noop") {
        durableVoice = voice;
        return voice;
      }
      if (result?.reason === "conflict") {
        // Pending choices share the old semantic baseline. Cancel that lane
        // rather than replaying it over another tab's winning selection.
        saveGeneration += 1;
        const current = await readDeviceRecord("voice");
        if (current?.data) restored = normalizeVoice(current.data);
        durableVoice = restored;
        publishVoice(restored);
      }
      if (cache === voice) {
        durableVoice = restored;
        publishVoice(restored);
      }
      throw new Error(result?.message || "Could not save voice settings in this browser.");
    } catch (err) {
      if (cache === voice) {
        publishVoice(restored);
      }
      throw err;
    }
  });
  saveTail = saving.catch(() => {});
  return saving.finally(() => { pendingSaves -= 1; });
}
