// Each operation has its own key: one tab acknowledging its click must never
// erase another tab's pending operation. No shared read/modify/write array.
export const PENDING_INTENT_KEY_PREFIX = "sdPendingIntent:";
export const LEGACY_PENDING_INTENT_KEY = "sdPendingIntent";

function storageOrNull() {
  try {
    return typeof localStorage === "undefined" ? null : localStorage;
  } catch (err) {
    return null;
  }
}

function validOp(op) {
  return op && typeof op.opId === "string" && op.opId.length > 0
    && ((Array.isArray(op.writes) && op.writes.length > 0)
      || (Array.isArray(op.tombstones) && op.tombstones.length > 0));
}

function keyFor(opId) {
  return `${PENDING_INTENT_KEY_PREFIX}${encodeURIComponent(opId)}`;
}

function readEntry(storage, key) {
  try {
    const entry = JSON.parse(storage.getItem(key) || "null");
    return entry && !entry.done && validOp(entry.op) ? entry : null;
  } catch (err) {
    return null;
  }
}

export function readPendingIntents() {
  const storage = storageOrNull();
  if (!storage) return [];
  const ops = new Map();
  const blocked = new Set();
  const legacy = readEntry(storage, LEGACY_PENDING_INTENT_KEY);
  if (legacy) {
    ops.set(legacy.op.opId, legacy.op);
    if (legacy.blocked) blocked.add(legacy.op.opId);
  }
  const keys = [];
  try {
    // Snapshot keys before reading; another tab may independently add or ack.
    for (let i = 0; i < storage.length; i += 1) {
      const key = storage.key(i);
      if (key?.startsWith(PENDING_INTENT_KEY_PREFIX)) keys.push(key);
    }
  } catch (err) {
    // A readable legacy operation can still be replayed if enumeration fails.
  }
  keys.forEach((key) => {
    const entry = readEntry(storage, key);
    if (!entry) return;
    const op = entry.op;
    try {
      if (key === keyFor(op.opId)) {
        ops.set(op.opId, op);
        if (entry.blocked) blocked.add(op.opId);
      }
    } catch (err) {
      // Ignore a malformed ID without hiding other pending operations.
    }
  });
  // Storage enumeration order is not a command order. A later click may use
  // entities/revisions created by an earlier uncommitted click, so replay its
  // immutable dependencies first. Missing dependencies were already acked.
  const pending = new Map(ops);
  const ordered = [];
  while (pending.size > 0) {
    const ready = Array.from(pending.values()).find((op) => (
      !blocked.has(op.opId) && !(Array.isArray(op.dependsOn) ? op.dependsOn : [])
        .some((id) => typeof id === "string" && pending.has(id))
    ));
    if (!ready) break;
    ordered.push(ready);
    pending.delete(ready.opId);
  }
  // A cycle (and anything depending on it) is left journaled for recovery,
  // rather than replaying a dependent command against an incomplete base.
  return ordered;
}

export function writePendingIntent(op) {
  const storage = storageOrNull();
  if (!storage || !validOp(op)) return false;
  try {
    // Restaging the same ID must not silently undo a retained conflict.
    if (readEntry(storage, keyFor(op.opId))?.blocked) return false;
    storage.setItem(keyFor(op.opId), JSON.stringify({ v: 1, op }));
    return true;
  } catch (err) {
    // Private mode or quota must not prevent the normal IndexedDB commit.
    return false;
  }
}

export function blockPendingIntent(opId, reason = "conflict") {
  const storage = storageOrNull();
  if (!storage || typeof opId !== "string" || !opId) return false;
  let changed = false;
  let modernKey;
  try {
    modernKey = keyFor(opId);
  } catch (err) {
    return false;
  }
  [modernKey, LEGACY_PENDING_INTENT_KEY].forEach((key) => {
    const entry = readEntry(storage, key);
    if (!entry || entry.op.opId !== opId) return;
    try {
      storage.setItem(key, JSON.stringify({ ...entry, blocked: true, blockReason: reason }));
      changed = true;
    } catch (err) {
      // A failed metadata write must not erase the operation's payload.
    }
  });
  return changed;
}

export function ackPendingIntent(opId) {
  const storage = storageOrNull();
  if (!storage || typeof opId !== "string" || !opId) return;
  try {
    storage.removeItem(keyFor(opId));
  } catch (err) {
    // Idempotent replay will handle a key that could not be removed.
  }
  try {
    const entry = JSON.parse(storage.getItem(LEGACY_PENDING_INTENT_KEY) || "null");
    const legacyId = entry?.op?.opId || entry?.opId;
    if (legacyId !== opId) return;
    storage.setItem(LEGACY_PENDING_INTENT_KEY, JSON.stringify({ v: 1, done: true, opId }));
  } catch (err) {
    // Leave an unreadable legacy entry untouched.
  }
}
