/**
 * Reclub identity on queue players.
 *
 * referenceId is kept as stored for compatibility. For guests (referenceType === 3)
 * that value is not a Reclub user id. reclubUserId is set only for non-guests.
 * Older records without these flags are not guessed from referenceId alone.
 */

export function isReclubGuestParticipant(participant) {
  if (!participant || typeof participant !== "object") return false;
  if (participant.isGuest === true) return true;
  return participant.referenceType === 3;
}

function hasExplicitNonGuestSignal(record) {
  if (!record || typeof record !== "object") return false;
  if (record.isGuest === false) return true;
  return record.referenceType != null && record.referenceType !== 3;
}

function presentId(value) {
  if (value == null) return null;
  const text = String(value).trim();
  return text === "" ? null : value;
}

/**
 * Identity for a meet participant or an already-mapped import row.
 * Non-guests copy referenceId onto reclubUserId. Guests keep referenceId and clear reclubUserId.
 */
export function reclubIdentityFromParticipant(participant = {}) {
  const referenceId = participant.referenceId ?? null;
  if (isReclubGuestParticipant(participant)) {
    return {
      referenceId,
      referenceType: participant.referenceType ?? 3,
      isGuest: true,
      reclubUserId: null,
    };
  }

  const explicitId = presentId(participant.reclubUserId);
  if (explicitId != null) {
    return {
      referenceId,
      referenceType: participant.referenceType ?? null,
      isGuest: false,
      reclubUserId: explicitId,
    };
  }

  if (hasExplicitNonGuestSignal(participant)) {
    return {
      referenceId,
      referenceType: participant.referenceType ?? null,
      isGuest: false,
      reclubUserId: presentId(referenceId),
    };
  }

  return {
    referenceId,
    referenceType: participant.referenceType ?? null,
    isGuest: null,
    reclubUserId: null,
  };
}

/**
 * Display identity for a stored player or a leaderboard row.
 * Derives reclubUserId from referenceId only when a non-guest signal is already on the record.
 */
export function resolveReclubDisplay(player = {}) {
  if (isReclubGuestParticipant(player)) {
    return { isGuest: true, reclubUserId: null, label: "Guest" };
  }

  const storedId = presentId(player.reclubUserId);
  if (storedId != null) {
    return { isGuest: false, reclubUserId: storedId, label: String(storedId) };
  }

  if (hasExplicitNonGuestSignal(player)) {
    const derived = presentId(player.referenceId);
    if (derived != null) {
      return { isGuest: false, reclubUserId: derived, label: String(derived) };
    }
  }

  return { isGuest: null, reclubUserId: null, label: "" };
}

/** Guests show "Guest". Manual players and unknown legacy rows show blank. */
export function formatReclubIdLabel(player) {
  return resolveReclubDisplay(player).label;
}

function normalizeGender(raw) {
  const rawGender = String(raw || "M").toUpperCase();
  if (rawGender.startsWith("F") || rawGender.startsWith("W")) return "F";
  if (rawGender === "MIXED") return "MX";
  return "M";
}

/**
 * Map a Reclub import payload into roster players.
 * Same-name collisions stay flagged. A repeated reclubUserId is kept once (first wins).
 */
export function buildReclubImportPlayers(participants, { now = Date.now() } = {}) {
  const list = Array.isArray(participants) ? participants : [];
  const duplicates = [];
  const newPlayers = [];
  const seenIds = new Set();
  const seenNames = new Set();
  const upName = (value) => String(value || "").trim().toUpperCase();
  const joinedYMD = new Date(now).toLocaleDateString("en-CA");
  let seq = 0;

  list.forEach((participant) => {
    const identity = reclubIdentityFromParticipant(participant);
    const idKey = identity.reclubUserId == null ? null : String(identity.reclubUserId).trim();
    if (idKey) {
      if (seenIds.has(idKey)) return;
      seenIds.add(idKey);
    }

    const upper = upName(participant?.name);
    if (seenNames.has(upper)) duplicates.push(upper);
    else seenNames.add(upper);

    const rawGender = participant?.gender || "M";
    newPlayers.push({
      id: now + seq,
      name: upper,
      level: "L.Inter",
      status: "stopped",
      matches: 0,
      waitStart: null,
      waitTime: 0,
      gender: normalizeGender(rawGender),
      joinedAt: now,
      joinedYMD,
      referenceId: identity.referenceId,
      referenceType: identity.referenceType,
      isGuest: identity.isGuest,
      reclubUserId: identity.reclubUserId,
      imageUrl: participant?.imageUrl ?? null,
      tags: Array.isArray(participant?.tags) ? participant.tags : [],
      paymentStatus: "unpaid",
      paymentMethod: null,
      isMember: !!participant?.isMember,
      price: 0,
      arrivalTime: null,
      pointDifferential: 0,
      longestWaitTimeMs: 0,
      totalMatchTimeMs: 0,
      averageMatchDurationMs: 0,
    });
    seq += 1;
  });

  return { players: newPlayers, duplicates: [...new Set(duplicates)] };
}
