import React, { useState, useMemo } from "react";
import toast, { Toaster } from "react-hot-toast";
import { useAppState } from "../../app/providers";
import { isPlayerUnpaid } from "../../common/utils/paymentStatus";
import { DEFAULT_OPEN_PLAY_FEE } from "../../common/utils/settingsDefaults";
import { getOpenPlayPrice, getRentalBookingFinancials } from "../../common/utils/pricing";
import { selectDashboardState } from "../../state/selectors";
import {
  buildRangeReport,
  computeDailyMetricsLastNDays,
  computeOccupancyBreakdownForRange,
  getRangeYMDBounds,
} from "./utils/reports";
import {
  isRentalBooking,
  isReportableOpSession,
  toYMDLocal,
  unpaidOpenPlayAmount,
} from "../../common/utils/reportPrimitives";
import MetricTile from "./components/MetricTile";
import HeroRevenue from "./components/HeroRevenue";
import TodayBoard, { buildTodayRentals } from "./components/TodayBoard";
import RevenueDetailModal from "./components/RevenueDetailModal";
import GameplayDetailModal from "./components/GameplayDetailModal";
import RentalDetailModal from "./components/RentalDetailModal";
import UnpaidDetailsModal from "./components/UnpaidDetailsModal";
import SettlePaymentModal from "./components/SettlePaymentModal";
import ReportGenerationModal from "./components/ReportGenerationModal";
import BookingManagerModal from "../calendar/v2/BookingManagerModal";
import { FileText, Users, CalendarDays, AlertCircle } from "lucide-react";

export default function DashboardV2Page() {
  const {
    bookingsV2 = {},
    slotsV2 = {},
    opSessions = [],
    currentOpSession,
    players = [],
    settings,
    calendarCourts = [],
    markAllSlotsPaidV2,
    updateOpSession,
    updateBookingV2,
    updateBookingAttendanceV2,
    deleteBookingV2,
    fetchBookingsForRange,
  } = useAppState(selectDashboardState);

  React.useEffect(() => {
    if (!fetchBookingsForRange) return;
    const today = new Date();
    const start = new Date(today);
    start.setDate(today.getDate() - 32);
    const end = new Date(today.getFullYear(), today.getMonth() + 1, 0);
    fetchBookingsForRange(toYMDLocal(start), toYMDLocal(end));
  }, [fetchBookingsForRange]);

  const [range, setRange] = useState("day");
  const [modalOpen, setModalOpen] = useState(null);
  const [viewBookingId, setViewBookingId] = useState(null);
  const [settleModalOpen, setSettleModalOpen] = useState(false);
  const [reportModalOpen, setReportModalOpen] = useState(false);
  const [settleTarget, setSettleTarget] = useState(null);

  const reportDate = toYMDLocal(new Date());
  const localYMD = reportDate;

  const reportData = useMemo(
    () => buildRangeReport(range, reportDate, opSessions, bookingsV2, slotsV2, settings, players),
    [range, reportDate, opSessions, bookingsV2, slotsV2, settings, players]
  );

  const formatLocalCurrency = (val) =>
    new Intl.NumberFormat("en-PH", { style: "currency", currency: "PHP", maximumFractionDigits: 0 }).format(val || 0);

  const incomeTotal = (reportData.openPlay?.totalIncome || 0) + (reportData.rentals?.totalIncome || 0);
  const rangeBounds = useMemo(() => getRangeYMDBounds(range, new Date(reportDate)), [range, reportDate]);

  const history30 = useMemo(
    () => computeDailyMetricsLastNDays(opSessions, bookingsV2, slotsV2, 30, reportDate),
    [bookingsV2, slotsV2, opSessions, reportDate]
  );

  const chartData = useMemo(() => {
    const series =
      range === "day"
        ? history30.slice(-7)
        : (reportData.dailyMetrics || []).length
          ? reportData.dailyMetrics
          : history30.slice(-7);
    return series.map((d) => {
      const raw = Number(d?.total);
      return {
        label: String(d?.date || "").slice(5) || "—",
        value: Number.isFinite(raw) && raw > 0 ? raw : 0,
      };
    });
  }, [range, reportData.dailyMetrics, history30]);

  const occupancy = useMemo(
    () =>
      computeOccupancyBreakdownForRange(
        bookingsV2,
        slotsV2,
        rangeBounds.startYmd,
        rangeBounds.endYmd,
        calendarCourts.length,
        settings
      ),
    [bookingsV2, slotsV2, rangeBounds, calendarCourts.length, settings]
  );

  const visitorsSparkline = history30.slice(-7).map((d) => d.visitorCount);
  const rentalsSparkline = useMemo(() => {
    const data = [];
    for (let i = 6; i >= 0; i -= 1) {
      const d = new Date(reportDate);
      d.setDate(d.getDate() - i);
      const ymd = toYMDLocal(d);
      const unique = new Set();
      Object.values(slotsV2 || {}).forEach((s) => {
        if (s && s.date === ymd && s.status !== "CANCELLED" && isRentalBooking(bookingsV2[s.bookingId])) {
          unique.add(s.bookingId);
        }
      });
      data.push(unique.size);
    }
    return data;
  }, [slotsV2, bookingsV2, reportDate]);

  const priorPeriodDelta = useMemo(() => {
    if (range === "day" || !history30.length) return null;
    const current = incomeTotal;
    const slice = range === "week" ? history30.slice(-14, -7) : history30.slice(0, Math.max(1, history30.length - 7));
    const prior = slice.reduce((sum, d) => sum + (d.total || 0), 0);
    if (prior <= 0) return null;
    const pct = Math.round(((current - prior) / prior) * 100);
    return { value: `${pct >= 0 ? "+" : ""}${pct}% vs prior`, direction: pct >= 0 ? "up" : "down" };
  }, [range, incomeTotal, history30]);

  const unpaidSessions = useMemo(() => {
    const { startYmd, endYmd } = rangeBounds;
    return opSessions.filter((s) => {
      if (!isReportableOpSession(s)) return false;
      const ymd = toYMDLocal(s.startedAt || s.endedAt || 0);
      if (ymd < startYmd || ymd > endYmd) return false;
      return s.players?.some((p) => isPlayerUnpaid(p.paymentStatus, p.paymentMethod));
    });
  }, [opSessions, rangeBounds]);

  const unpaidRentals = useMemo(() => {
    const { startYmd, endYmd } = rangeBounds;
    const result = [];
    Object.values(bookingsV2 || {}).forEach((b) => {
      if (!isRentalBooking(b)) return;
      const { slots: bSlots, balance, amountPaid, totalDue } = getRentalBookingFinancials(b, slotsV2);
      if (balance <= 0) return;
      const datedSlots = bSlots.filter((s) => s.date);
      if (!datedSlots.length) return;
      const inRange = datedSlots.some((s) => s.date >= startYmd && s.date <= endYmd);
      if (!inRange) return;

      datedSlots.sort((x, y) => {
        if (x.date !== y.date) return x.date.localeCompare(y.date);
        return (x.startTime || 0) - (y.startTime || 0);
      });
      const start = datedSlots[0];
      const end = datedSlots[datedSlots.length - 1];
      const courtIds = Array.from(new Set(datedSlots.map((s) => s.courtId))).sort().join(", ");
      const formatTime = (val) => {
        if (typeof val === "number") {
          const h = Math.floor(val / 60);
          const m = val % 60;
          const ampm = h >= 12 ? "PM" : "AM";
          const h12 = h % 12 || 12;
          return `${h12}:${String(m).padStart(2, "0")} ${ampm}`;
        }
        return new Date(val).toLocaleTimeString([], { hour: "2-digit", minute: "2-digit", hour12: true });
      };

      result.push({
        ...b,
        id: b.id,
        rentalPrice: balance,
        totalDue,
        amountPaid,
        paymentStatus: amountPaid > 0 ? "PARTIAL" : "UNPAID",
        renterName: b.renter?.name || b.title || "Unknown",
        date: start?.date || "",
        courtName: `Court ${courtIds}`,
        startTime: formatTime(start?.startTime),
        endTime: formatTime(end?.endTime),
      });
    });
    return result;
  }, [slotsV2, bookingsV2, rangeBounds]);

  const unpaidStats = useMemo(() => {
    let count = 0;
    let amount = 0;
    unpaidSessions.forEach((s) => {
      s.players.forEach((p) => {
        if (isPlayerUnpaid(p.paymentStatus, p.paymentMethod)) {
          count += 1;
          amount += unpaidOpenPlayAmount(p, settings, s.sessionFee);
        }
      });
    });
    unpaidRentals.forEach((b) => {
      count += 1;
      amount += b.rentalPrice || 0;
    });
    return { count, amount };
  }, [unpaidSessions, unpaidRentals, settings]);

  const todayRentals = useMemo(
    () => buildTodayRentals(bookingsV2, slotsV2, localYMD),
    [bookingsV2, slotsV2, localYMD]
  );

  const liveUnpaidCount = useMemo(() => {
    if (!currentOpSession) return 0;
    return players.filter((p) => isPlayerUnpaid(p.paymentStatus, p.paymentMethod)).length;
  }, [currentOpSession, players]);

  const avgWaitSubtext =
    reportData.games?.avgWaitMs > 0
      ? `Avg wait ${Math.round(reportData.games.avgWaitMs / 60000)}m`
      : "Total check-ins";

  const handleSettleRental = (rentalIds) => {
    const ids = Array.isArray(rentalIds) ? rentalIds : [rentalIds];
    if (ids.length > 0) {
      setViewBookingId(ids[0]);
      setSettleTarget({ type: "rental", ids });
    }
  };

  const handleSettleSessionPlayer = (sessionId, playerId) => {
    const session = opSessions.find((s) => s.id === sessionId);
    const player = session?.players?.find((p) => p.id === playerId);
    const amount =
      unpaidOpenPlayAmount(player, settings, session?.sessionFee) ||
      player?.price ||
      0;
    setSettleTarget({ type: "session_player", sessionId, playerId, amount });
    setSettleModalOpen(true);
  };

  const onSettleConfirm = (method) => {
    if (!settleTarget) return;

    if (settleTarget.type === "rental") {
      settleTarget.ids.forEach((id) => {
        if (markAllSlotsPaidV2) markAllSlotsPaidV2(id, method);
      });
      toast.success("Rental has been successfully settled.");
    } else if (settleTarget.type === "session_player") {
      const { sessionId, playerId } = settleTarget;
      const session = opSessions.find((s) => s.id === sessionId);
      if (session) {
        const updatedPlayers = session.players.map((p) => {
          if (p.id !== playerId) return p;
          if (method === "unpaid") {
            return { ...p, paymentStatus: "unpaid", paymentMethod: null, price: 0 };
          }
          if (method === "free") {
            return { ...p, paymentStatus: "free", paymentMethod: "free", price: 0 };
          }
          const fee = settings?.defaultOpFee ?? DEFAULT_OPEN_PLAY_FEE;
          const price =
            p.price > 0
              ? p.price
              : getOpenPlayPrice(settings, {
                  isMember: !!p.isMember,
                  sessionFee: session.sessionFee ?? fee,
                });
          return { ...p, paymentStatus: "paid", paymentMethod: method, price };
        });
        if (updateOpSession) {
          updateOpSession(sessionId, { players: updatedPlayers });
          toast.success("Player has been successfully settled.");
        }
      }
    }
    setSettleModalOpen(false);
    setSettleTarget(null);
  };

  return (
    <div className="h-full overflow-y-auto admin-page-bg p-6 font-sans">
      <Toaster position="top-center" reverseOrder={false} />

      <div className="flex flex-col md:flex-row md:items-center justify-between mb-8 gap-4">
        <div>
          <h1 className="text-3xl page-title">Dashboard</h1>
          <p className="text-slate-500 text-sm mt-1">Overview of your facility&apos;s performance.</p>
        </div>
        <div className="flex items-center gap-3 bg-white p-1.5 rounded-xl border border-slate-200 shadow-sm">
          {["day", "week", "month"].map((r) => (
            <button
              key={r}
              type="button"
              onClick={() => setRange(r)}
              className={`px-4 py-1.5 rounded-lg text-xs font-semibold transition-all ${
                range === r ? "bg-pt-navy text-white shadow-md" : "text-pt-navy/60 hover:bg-pt-navy/5"
              }`}
            >
              {r === "day" ? "Today" : r === "week" ? "This Week" : "This Month"}
            </button>
          ))}
        </div>
        <button
          type="button"
          onClick={() => setReportModalOpen(true)}
          className="flex items-center gap-2 px-4 py-2 bg-pt-navy hover:bg-pt-navy-light text-white text-xs font-bold rounded-lg shadow-sm transition-colors"
        >
          <FileText className="w-4 h-4" />
          <span>Generate Report</span>
        </button>
      </div>

      <HeroRevenue
        totalIncome={incomeTotal}
        openPlayIncome={reportData.openPlay?.totalIncome || 0}
        rentalIncome={reportData.rentals?.totalIncome || 0}
        chartData={chartData}
        occupancy={occupancy}
        formatCurrency={formatLocalCurrency}
      />

      <div className="grid grid-cols-1 md:grid-cols-3 gap-6 mb-8">
        <MetricTile
          title={`Open Play check-ins (${range})`}
          value={reportData.openPlay?.totalPlayers ?? 0}
          subtext={avgWaitSubtext}
          icon={<Users className="w-5 h-5" />}
          colorClass="text-indigo-600"
          chartData={visitorsSparkline}
          trend={priorPeriodDelta}
          onViewReport={() => setModalOpen("gameplay")}
        />
        <MetricTile
          title={`Rentals (${range})`}
          value={reportData.rentals?.totalRentals ?? 0}
          subtext="Rental bookings"
          icon={<CalendarDays className="w-5 h-5" />}
          colorClass="text-purple-600"
          chartData={rentalsSparkline}
          onViewReport={() => setModalOpen("rental")}
        />
        <MetricTile
          title={`Unpaid (${range})`}
          value={formatLocalCurrency(unpaidStats.amount)}
          subtext={`${unpaidStats.count} pending items`}
          icon={<AlertCircle className="w-5 h-5" />}
          colorClass="text-rose-600"
          trend={unpaidStats.count > 0 ? { value: "Action needed", direction: "down" } : null}
          onViewReport={() => setModalOpen("unpaid")}
        />
      </div>

      <TodayBoard
        localYMD={localYMD}
        todayRentals={todayRentals}
        currentOpSession={currentOpSession}
        livePlayerCount={players.length}
        liveUnpaidCount={liveUnpaidCount}
        onOpenBooking={setViewBookingId}
        formatCurrency={formatLocalCurrency}
      />

      <ReportGenerationModal isOpen={reportModalOpen} onClose={() => setReportModalOpen(false)} />
      <RevenueDetailModal
        isOpen={modalOpen === "revenue"}
        onClose={() => setModalOpen(null)}
        initialRange={range}
        reportDate={reportDate}
        opSessions={opSessions}
        bookingsV2={bookingsV2}
        slotsV2={slotsV2}
        settings={settings}
        players={players}
      />
      <GameplayDetailModal isOpen={modalOpen === "gameplay"} onClose={() => setModalOpen(null)} data={reportData} range={range} />
      <RentalDetailModal isOpen={modalOpen === "rental"} onClose={() => setModalOpen(null)} data={reportData} range={range} />
      <UnpaidDetailsModal
        isOpen={modalOpen === "unpaid"}
        onClose={() => setModalOpen(null)}
        unpaidSessions={unpaidSessions}
        unpaidRentals={unpaidRentals}
        onSettleRental={handleSettleRental}
        onSettleSessionPlayer={handleSettleSessionPlayer}
        onViewBooking={(id) => setViewBookingId(id)}
        defaultOpFee={settings?.defaultOpFee ?? DEFAULT_OPEN_PLAY_FEE}
      />
      <SettlePaymentModal
        isOpen={settleModalOpen}
        onClose={() => {
          setSettleModalOpen(false);
          setSettleTarget(null);
        }}
        onSettle={onSettleConfirm}
        title={settleTarget?.type === "rental" ? "Settle Rental Group" : "Settle Player Payment"}
        amount={settleTarget?.amount}
      />

      {viewBookingId && (
        <BookingManagerModal
          isOpen={!!viewBookingId}
          onClose={() => {
            setViewBookingId(null);
            setSettleTarget(null);
          }}
          booking={bookingsV2[viewBookingId]}
          slots={Object.values(slotsV2).filter((s) => s.bookingId === viewBookingId && s.status !== "CANCELLED")}
          allSlots={Object.values(slotsV2)}
          courts={calendarCourts}
          settings={settings}
          defaultRentalRate={settings?.defaultRentalRate}
          readOnly={bookingsV2[viewBookingId]?.source === "WEBSITE"}
          initialTab={settleTarget ? "slots" : "overview"}
          onDeleteBooking={async (id, options) => {
            if (!deleteBookingV2) return;
            await toast.promise(deleteBookingV2(id, options), {
              loading: "Cancelling booking...",
              success: "Booking cancelled.",
              error: (err) => err.message || "Cancel failed",
            });
            setViewBookingId(null);
            setSettleTarget(null);
          }}
          onUpdateBooking={(id, data) => {
            if (updateBookingV2) {
              updateBookingV2(id, data);
              toast.success("Booking updated securely.");
              setViewBookingId(null);
              setSettleTarget(null);
            }
          }}
          onUpdateAttendance={updateBookingAttendanceV2}
        />
      )}
    </div>
  );
}
