import {
  APPLIED_OP_CAP,
  SYNC_CHANNEL,
  SYNC_PING_KEY,
  applyOp,
  backfillRecordsFromDocument,
  conflictToast,
  countLiveRecords,
  encodeSyncPing,
  decodeSyncPing,
  entityKey,
  projectEntities,
} from "./entityOps";
import {
  IDB_ENTITIES,
  IDB_RECORD_KEY,
  isDisplaySurface,
  isIdbDisabled,
  openSouthDinkersDb,
  parseEnvelope,
  readKvRecord,
} from "./storage";

const META_KEY = "meta:sync";
const VOICE_KEY = "voicePrefs";
const LEADERBOARD_KEY = "southDinkersLeaderboardDisplayUntil";

const memoryEntities = new Map();

function memoryBackend() {
  return process.env.NODE_ENV === "test";
}

export function resetEntityStoreForTests() {
  memoryEntities.clear();
}

if (typeof window !== "undefined") {
  window.__sdResetEntities = resetEntityStoreForTests;
}

export function readEntitiesForTests() {
  return Array.from(memoryEntities.values()).map((row) => ({ ...row, data: row.data }));
}

export function seedEntityForTests(record) {
  if (record?.key) memoryEntities.set(record.key, record);
}

function req(request) {
  return new Promise((resolve, reject) => {
    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error || new Error("IndexedDB request failed"));
  });
}

let lockTail = Promise.resolve();
const LOCK_WAIT_MS = 8000;

export function withLock(fn) {
  if (typeof navigator !== "undefined" && navigator.locks?.request) {
    const signal = typeof AbortSignal !== "undefined" && typeof AbortSignal.timeout === "function"
      ? AbortSignal.timeout(LOCK_WAIT_MS)
      : undefined;
    return navigator.locks.request(
      "sd-op",
      signal ? { mode: "exclusive", signal } : { mode: "exclusive" },
      () => fn()
    );
  }
  let timer = 0;
  let cancelled = false;
  const waitError = new Error("Timed out waiting for the save lock.");
  waitError.name = "AbortError";
  const timeout = new Promise((_, reject) => {
    timer = setTimeout(() => {
      cancelled = true;
      reject(waitError);
    }, LOCK_WAIT_MS);
  });
  const run = lockTail.then(() => {
    if (cancelled) throw waitError;
    // This timeout covers queue wait only. Once started, the transaction's
    // own completion/abort is authoritative; it must not commit after a timeout.
    if (timer) clearTimeout(timer);
    return fn();
  });
  lockTail = run.then(() => {}, () => {});
  return Promise.race([run, timeout]).finally(() => {
    if (timer) clearTimeout(timer);
  });
}

function memoryMap() {
  const map = {};
  memoryEntities.forEach((row, key) => {
    map[key] = row;
  });
  return map;
}

async function readAllEntities(db) {
  if (memoryBackend()) return memoryMap();
  const database = db || await openSouthDinkersDb();
  const close = !db;
  try {
    if (!database.objectStoreNames.contains(IDB_ENTITIES)) return {};
    const tx = database.transaction(IDB_ENTITIES, "readonly");
    const rows = await req(tx.objectStore(IDB_ENTITIES).getAll());
    const map = {};
    (rows || []).forEach((row) => {
      if (row?.key) map[row.key] = row;
    });
    return map;
  } finally {
    if (close) database.close();
  }
}

function backfillRows(existing, parsed, deviceRows) {
  const plan = planBackfill(Object.values(existing), parsed);
  if (plan.action === "skip") return [];
  const meta = metaRecord({
    ...(plan.action === "copy" ? parsed?.meta?.migrations || {} : {}),
    entityBackfillAt: new Date().toISOString(),
  }, plan.meta);
  if (plan.action === "stamp") return [meta];
  return [...plan.records, ...deviceRows.filter((row) => !existing[row.key]), meta];
}

async function backfillEntitiesAtomically(parsed, deviceRows = []) {
  if (memoryBackend()) {
    return withLock(() => {
      backfillRows(memoryMap(), parsed, deviceRows).forEach((row) => memoryEntities.set(row.key, row));
      return memoryMap();
    });
  }
  const db = await openSouthDinkersDb();
  try {
    return await new Promise((resolve, reject) => {
      const tx = db.transaction(IDB_ENTITIES, "readwrite");
      const store = tx.objectStore(IDB_ENTITIES);
      let current = {};
      const getAll = store.getAll();
      getAll.onsuccess = () => {
        try {
          current = Object.fromEntries((getAll.result || []).map((row) => [row.key, row]));
          // Recheck the migration stamp and live rows inside the write transaction.
          // A delayed second tab must never overwrite a first tab's live edits.
          backfillRows(current, parsed, deviceRows).forEach((row) => {
            store.put(row);
            current[row.key] = row;
          });
        } catch (err) {
          try { tx.abort(); } catch (abortErr) { /* transaction already stopped */ }
          reject(err);
        }
      };
      getAll.onerror = () => reject(getAll.error || new Error("IndexedDB read failed"));
      tx.oncomplete = () => resolve(current);
      tx.onerror = () => reject(tx.error || new Error("IndexedDB transaction failed"));
      tx.onabort = () => reject(tx.error || new Error("IndexedDB transaction aborted"));
    });
  } finally {
    db.close();
  }
}

function projectWithMeta(entities, kvParsed) {
  const projected = projectEntities(entities);
  const metaRecord = entities[META_KEY];
  return {
    ...projected,
    // Role stays on this window. Do not restore a logged-out role from the store.
    userRole: null,
    staffName: "",
    meta: {
      ...(kvParsed?.meta || {}),
      migrations: {
        ...(kvParsed?.meta?.migrations || {}),
        ...(metaRecord?.migrations || {}),
      },
      seedSource: metaRecord?.seedSource || kvParsed?.meta?.seedSource || kvParsed?.seedSource || null,
    },
    version: kvParsed?.version,
    entityRevs: projected.entityRevs,
  };
}

function parseJson(raw) {
  if (raw == null || raw === "") return null;
  if (typeof raw === "string") {
    try {
      return JSON.parse(raw);
    } catch (err) {
      return null;
    }
  }
  return typeof raw === "object" ? raw : null;
}

function deviceRecord(id, data) {
  return {
    key: `device:${id}`,
    kind: "device",
    id,
    rev: 1,
    updatedAt: Date.now(),
    actorId: "migration",
    deleted: false,
    deletedAt: null,
    data,
  };
}

function metaRecord(extraMigrations, previous) {
  const now = new Date().toISOString();
  return {
    key: META_KEY,
    kind: "meta",
    id: "sync",
    appliedOpIds: previous?.appliedOpIds || [],
    migrations: {
      ...(previous?.migrations || {}),
      ...(extraMigrations || {}),
      entityBackfillAt: previous?.migrations?.entityBackfillAt || extraMigrations?.entityBackfillAt || now,
      entityCutover: true,
    },
    seedSource: previous?.seedSource || null,
    opCursor: previous?.opCursor || 0,
  };
}

/**
 * Copy kv into entity rows at most once.
 * Live rows are never replaced with rev-1 copies. A database that already
 * has entities only receives the backfill stamp.
 */
export function planBackfill(existingRows, parsed) {
  const rows = Array.isArray(existingRows) ? existingRows : [];
  const meta = rows.find((row) => row?.key === META_KEY) || null;
  if (meta?.migrations?.entityBackfillAt) return { action: "skip", meta };
  const live = rows.filter((row) => row && !row.deleted && row.kind !== "meta" && row.key !== META_KEY);
  if (live.length > 0) return { action: "stamp", meta };
  return { action: "copy", meta, records: backfillRecordsFromDocument(parsed) };
}

/**
 * Copy kv into entities at most once. Never overwrites an existing kv record
 * and never reseeds over live entity rows.
 */
export async function loadAuthoritativeState(options = {}) {
  if (typeof window !== "undefined" && window.__sdPreseed) {
    try {
      await window.__sdPreseed;
    } catch (err) {
      console.warn("Preseed wait failed", err);
    }
  }
  if (isIdbDisabled() && !memoryBackend()) return null;
  const entities = await readAllEntities();
  const meta = entities[META_KEY];
  const bootstrapped = options.bootstrapped || null;
  if (meta?.migrations?.entityBackfillAt) {
    return projectWithMeta(entities, bootstrapped);
  }
  if (countLiveRecords(entities) > 0) {
    return projectWithMeta(await backfillEntitiesAtomically(bootstrapped || {}), bootstrapped);
  }
  const recordRaw = await readKvRecord(IDB_RECORD_KEY);
  if (recordRaw == null || recordRaw === "") return null;
  const parsed = parseEnvelope(recordRaw) || bootstrapped || {};
  const deviceRows = [];
  const voiceRaw = parseJson(await readKvRecord(VOICE_KEY));
  if (voiceRaw && !entities["device:voice"]) {
    deviceRows.push(deviceRecord("voice", {
      voiceName: voiceRaw.voiceName || "",
      rate: Number(voiceRaw.rate ?? 0.9),
      pitch: Number(voiceRaw.pitch ?? 1),
    }));
  }
  const boardRaw = parseJson(await readKvRecord(LEADERBOARD_KEY));
  if (boardRaw && !entities["device:leaderboardDisplay"]) {
    const until = Number(boardRaw.until);
    deviceRows.push(deviceRecord("leaderboardDisplay", {
      until: Number.isFinite(until) ? until : 0,
      mode: boardRaw.mode === "top5" ? "top5" : "full",
    }));
  }
  return projectWithMeta(await backfillEntitiesAtomically(parsed, deviceRows), parsed);
}

function writerAllowed(op, writer) {
  if (writer === "display" || isDisplaySurface()) {
    return { ok: false, reason: "read-only" };
  }
  if (writer === "leaderboard") {
    const writes = op?.writes || [];
    const tombstones = op?.tombstones || [];
    const writeOk = writes.every((write) =>
      write.kind === "match" || write.kind === "session" || write.kind === "player" || write.kind === "hold"
    );
    const tombOk = tombstones.every((tomb) => tomb.kind === "match");
    if (!writeOk || !tombOk) return { ok: false, reason: "read-only" };
  }
  return null;
}

let pauseUntil = 0;
const pausedMessages = [];
let pauseTimer = 0;

function deliver(message) {
  let bc;
  try {
    if (typeof BroadcastChannel !== "undefined") {
      bc = new BroadcastChannel(SYNC_CHANNEL);
      bc.postMessage(message);
    }
  } catch (err) {
    console.warn("Broadcast sync failed; using the storage ping", err);
  } finally {
    try { bc?.close(); } catch (err) { /* notification failure never changes commit success */ }
  }
  try {
    if (typeof localStorage !== "undefined") {
      localStorage.setItem(SYNC_PING_KEY, encodeSyncPing(message));
    }
  } catch (err) {
    console.warn("Sync ping failed", err);
  }
}

function publish(message) {
  if (Date.now() < pauseUntil) {
    pausedMessages.push(message);
    return;
  }
  deliver(message);
}

export function pauseOutbound(ms = 2000) {
  pauseUntil = Date.now() + ms;
  if (pauseTimer) clearTimeout(pauseTimer);
  pauseTimer = setTimeout(() => {
    pauseUntil = 0;
    flushOutbound();
  }, ms);
}

export function flushOutbound() {
  pauseUntil = 0;
  if (pauseTimer) {
    clearTimeout(pauseTimer);
    pauseTimer = 0;
  }
  const queued = pausedMessages.splice(0, pausedMessages.length);
  queued.forEach((message) => deliver(message));
}

function stripResult(record) {
  const { rebased, ...rest } = record;
  return rest;
}

function resultFromApplied(applied, op) {
  return {
    ok: applied.ok,
    reason: applied.reason,
    idempotent: !!applied.idempotent,
    rebased: !!applied.rebased,
    conflicts: applied.conflicts || [],
    records: applied.records || [],
    tombstones: applied.tombstones || [],
    current: applied.current || {},
    message: applied.ok ? "" : conflictToast(applied.conflicts),
    op: applied.op || op,
  };
}

function rememberApplied(meta, activeOp, applied) {
  const appliedOpIds = (meta?.appliedOpIds || []).concat(activeOp.opId).slice(-APPLIED_OP_CAP);
  return {
    ...(meta || {}),
    key: META_KEY,
    kind: "meta",
    id: "sync",
    appliedOpIds,
    migrations: { ...(meta?.migrations || {}), entityCutover: true },
    opCursor: (Number(meta?.opCursor) || 0) + 1,
  };
}

async function commitMemory(op, options) {
  let activeOp = op;
  // The whole club is in view so a status change can retarget a queue row
  // that this op did not name.
  const records = memoryMap();
  if (typeof options.rebaseLive === "function") {
    const rebuilt = options.rebaseLive(records);
    if (!rebuilt) {
      return resultFromApplied({
        ok: true,
        reason: "noop",
        idempotent: true,
        records: [],
        tombstones: [],
        current: { ...records },
      }, op);
    }
    activeOp = rebuilt;
  }
  const meta = records[META_KEY] || {
    key: META_KEY,
    kind: "meta",
    id: "sync",
    appliedOpIds: [],
    migrations: { entityCutover: true },
  };
  const applied = applyOp({ records, appliedOpIds: meta.appliedOpIds || [] }, activeOp);
  applied.op = activeOp;
  if (applied.ok && !applied.idempotent) {
    applied.records.forEach((record) => memoryEntities.set(record.key, stripResult(record)));
    applied.tombstones.forEach((record) => memoryEntities.set(record.key, stripResult(record)));
    memoryEntities.set(META_KEY, rememberApplied(meta, activeOp));
  }
  return resultFromApplied(applied, activeOp);
}

export async function commitOp(op, options = {}) {
  const blocked = writerAllowed(op, options.writer);
  if (blocked) return blocked;
  if (!op?.opId) return { ok: false, reason: "invalid" };
  if ((isIdbDisabled() || typeof indexedDB === "undefined") && !memoryBackend()) {
    return { ok: false, reason: "unavailable", message: "IndexedDB is unavailable. Reopen this page and try again." };
  }
  try {
    return await withLock(async () => {
      const outcome = memoryBackend()
        ? await commitMemory(op, options)
        : await commitIndexed(op, options);
      if (outcome.ok && !outcome.idempotent) {
        const keysOut = []
          .concat(outcome.records || [], outcome.tombstones || [])
          .map((record) => record.key);
        publish({
          type: "COMMIT",
          opId: outcome.op?.opId || op.opId,
          actorId: op.actorId || null,
          keys: keysOut,
        });
      }
      return outcome;
    });
  } catch (err) {
    console.warn("Club op failed", err);
    return { ok: false, reason: "abort", message: err?.message || "Could not save." };
  }
}

async function commitIndexed(op, options) {
  const db = await openSouthDinkersDb();
  try {
    const opKeys = (value) => {
      const keys = new Set([META_KEY]);
      (value?.writes || []).forEach((write) => keys.add(entityKey(write.kind, write.id)));
      (value?.tombstones || []).forEach((tomb) => keys.add(entityKey(tomb.kind, tomb.id)));
      return keys;
    };
    return await new Promise((resolve, reject) => {
      const tx = db.transaction(IDB_ENTITIES, "readwrite");
      const store = tx.objectStore(IDB_ENTITIES);
      const records = {};
      const seen = new Set();
      let applied = null;
      let activeOp = op;
      let didRebase = false;

      const applyNow = () => {
        try {
          if (!didRebase && typeof options.rebaseLive === "function") {
            didRebase = true;
            const rebuilt = options.rebaseLive(records);
            if (!rebuilt) {
              applied = {
                ok: true,
                reason: "noop",
                idempotent: true,
                records: [],
                tombstones: [],
                current: { ...records },
                op: activeOp,
              };
              return;
            }
            activeOp = rebuilt;
            const extra = [...opKeys(activeOp)].filter((key) => !seen.has(key));
            if (extra.length) {
              readKeys(extra, applyNow);
              return;
            }
          }
          const meta = records[META_KEY] || {
            key: META_KEY,
            kind: "meta",
            id: "sync",
            appliedOpIds: [],
            migrations: { entityCutover: true },
          };
          applied = applyOp({ records, appliedOpIds: meta.appliedOpIds || [] }, activeOp);
          applied.op = activeOp;
          if (!applied.ok || applied.idempotent) return;
          applied.records.forEach((record) => store.put(stripResult(record)));
          applied.tombstones.forEach((record) => store.put(stripResult(record)));
          store.put(rememberApplied(meta, activeOp));
        } catch (err) {
          try { tx.abort(); } catch (abortErr) { /* already aborted */ }
          reject(err);
        }
      };

      const readKeys = (keyList, done) => {
        const missing = keyList.filter((key) => !seen.has(key));
        if (!missing.length) {
          done();
          return;
        }
        let left = missing.length;
        missing.forEach((key) => {
          seen.add(key);
          const request = store.get(key);
          request.onsuccess = () => {
            if (request.result) records[key] = request.result;
            left -= 1;
            if (left === 0) done();
          };
          request.onerror = () => reject(request.error || new Error("IndexedDB read failed"));
        });
      };

      const getAll = store.getAll();
      getAll.onerror = () => reject(getAll.error || new Error("IndexedDB read failed"));
      getAll.onsuccess = () => {
        (getAll.result || []).forEach((row) => {
          if (!row?.key) return;
          records[row.key] = row;
          seen.add(row.key);
        });
        seen.add(META_KEY);
        applyNow();
      };
      tx.oncomplete = () => resolve(resultFromApplied(applied || { ok: false, reason: "abort", message: "Empty transaction." }, op));
      tx.onerror = () => reject(tx.error || new Error("IndexedDB transaction failed"));
      tx.onabort = () => reject(tx.error || new Error("IndexedDB transaction aborted"));
    });
  } finally {
    db.close();
  }
}

export async function readChangedRecords(keys) {
  if ((isIdbDisabled() || typeof indexedDB === "undefined") && !memoryBackend()) {
    return { records: [], tombstones: [] };
  }
  if (Array.isArray(keys) && keys.length === 0) return { records: [], tombstones: [] };
  if (memoryBackend()) {
    const rows = Array.isArray(keys)
      ? keys.map((key) => memoryEntities.get(key)).filter(Boolean)
      : Array.from(memoryEntities.values());
    return splitRows(rows);
  }
  const db = await openSouthDinkersDb();
  try {
    const tx = db.transaction(IDB_ENTITIES, "readonly");
    const store = tx.objectStore(IDB_ENTITIES);
    const rows = Array.isArray(keys)
      ? await Promise.all(keys.map((key) => req(store.get(key))))
      : await req(store.getAll());
    return splitRows(rows || []);
  } finally {
    db.close();
  }
}

function splitRows(rows) {
  const records = [];
  const tombstones = [];
  (rows || []).forEach((row) => {
    if (!row) return;
    if (row.deleted) tombstones.push(row);
    else records.push(row);
  });
  return { records, tombstones };
}

export function subscribeLiveClub(onChange) {
  if (typeof window === "undefined") return () => {};
  let bc;
  try {
    if (typeof BroadcastChannel !== "undefined") {
      bc = new BroadcastChannel(SYNC_CHANNEL);
      bc.onmessage = (msg) => {
        const data = msg?.data;
        if (!data || data.type !== "COMMIT") return;
        onChange(data);
      };
    }
  } catch (err) {
    console.warn("Broadcast subscription failed; using storage events", err);
  }
  const onStorage = (event) => {
    if (event.key !== SYNC_PING_KEY || !event.newValue) return;
    const ping = decodeSyncPing(event.newValue);
    onChange({ type: "PING", opId: ping.opId, keys: ping.keys });
  };
  window.addEventListener("storage", onStorage);
  return () => {
    try { bc?.close(); } catch (err) { /* listener cleanup must still complete */ }
    window.removeEventListener("storage", onStorage);
  };
}

export async function readDeviceRecord(id) {
  const key = `device:${id}`;
  if (memoryBackend()) {
    const row = memoryEntities.get(key);
    return row && !row.deleted ? row : null;
  }
  if (typeof indexedDB === "undefined") return null;
  const db = await openSouthDinkersDb();
  try {
    const tx = db.transaction(IDB_ENTITIES, "readonly");
    const row = await req(tx.objectStore(IDB_ENTITIES).get(key));
    return row && !row.deleted ? row : null;
  } catch (err) {
    console.warn("Device record read failed", err);
    return null;
  } finally {
    db.close();
  }
}
