/**
 * Open Play payment status helpers.
 * Canonical unpaid status: "unpaid". Legacy "not_paid" is accepted on read.
 * Free counts as paid for headcount but price is always 0.
 */

const PAID_METHODS = new Set(["cash", "gcash", "gotyme", "bank", "bulk"]);

export const PAYMENT_METHOD_LABELS = {
  cash: "Cash",
  gcash: "GCash",
  gotyme: "GoTyme",
  bank: "Bank",
  bulk: "Bulk",
  free: "Free",
};

export const PAID_PAYMENT_BUCKETS = ["cash", "gcash", "gotyme", "bank"];

export const formatPaymentMethodLabel = (paymentMethod) => {
  const method = String(paymentMethod || "").toLowerCase();
  return PAYMENT_METHOD_LABELS[method] || "Cash";
};

export const normalizePaymentStatus = (paymentStatus, paymentMethod = null) => {
  let status = paymentStatus;
  if (status && typeof status === "object") {
    status = status.paymentStatus;
  }
  const s = String(status || "").toLowerCase();
  const method = String(paymentMethod || "").toLowerCase();

  if (!s || s === "not_paid" || s === "unpaid") return "unpaid";
  if (s === "free" || method === "free") return "free";
  if (s === "paid" || PAID_METHODS.has(s) || PAID_METHODS.has(method)) return "paid";
  return "unpaid";
};

export const normalizePaymentMethod = (paymentStatus, paymentMethod = null) => {
  const status = normalizePaymentStatus(paymentStatus, paymentMethod);
  if (status === "unpaid") return null;
  if (status === "free") return "free";

  const method = String(paymentMethod || "").toLowerCase();
  if (PAID_METHODS.has(method)) return method;

  const s = String(paymentStatus || "").toLowerCase();
  if (PAID_METHODS.has(s)) return s;

  return method || "cash";
};

export const isPlayerUnpaid = (paymentStatus, paymentMethod = null) =>
  normalizePaymentStatus(paymentStatus, paymentMethod) === "unpaid";

export const isPlayerPaid = (paymentStatus, paymentMethod = null) =>
  !isPlayerUnpaid(paymentStatus, paymentMethod);

export const isPlayerFree = (paymentStatus, paymentMethod = null) =>
  normalizePaymentStatus(paymentStatus, paymentMethod) === "free";

/** Paid with a collectible amount (excludes free and unpaid). */
export const isPlayerPaidWithCharge = (paymentStatus, paymentMethod = null) =>
  normalizePaymentStatus(paymentStatus, paymentMethod) === "paid";

export const classifyPlayerPaymentBucket = (paymentStatus, paymentMethod = null) => {
  const status = normalizePaymentStatus(paymentStatus, paymentMethod);
  if (status === "unpaid") return "unpaid";
  if (status === "free") return "free";

  const method = normalizePaymentMethod(paymentStatus, paymentMethod);
  if (method.includes("gcash")) return "gcash";
  if (method.includes("gotyme")) return "gotyme";
  if (method.includes("bank")) return "bank";
  return "cash";
};

export const normalizePlayerPaymentRecord = (raw = {}) => {
  let status = raw.paymentStatus;
  if (status && typeof status === "object") {
    status = status.paymentStatus;
  }

  const norm = normalizePaymentStatus(status, raw.paymentMethod);
  if (norm === "unpaid") {
    return { paymentStatus: "unpaid", paymentMethod: null, price: 0 };
  }
  if (norm === "free") {
    return { paymentStatus: "free", paymentMethod: "free", price: 0 };
  }

  const paymentMethod = normalizePaymentMethod(status, raw.paymentMethod);
  const price =
    typeof raw.price === "number" && !Number.isNaN(raw.price) ? raw.price : 0;

  return { paymentStatus: "paid", paymentMethod, price };
};
