import config from '../../config';

export async function fetchRentalQuote(slots, renter = {}, bookingId = null, signal) {
  const response = await fetch(`${process.env.REACT_APP_API_URL || ''}/api/v1/calendar/quote`, {
    method: 'POST', headers: { 'Content-Type': 'application/json' }, signal,
    body: JSON.stringify({ facility_id: config.facilityId, bookingId, slots, renter_details: renter }),
  });
  const data = await response.json();
  if (!response.ok) throw new Error(data.message || data.error || 'Could not refresh rental pricing.');
  return data;
}
