import React from 'react';
import { resolveRentalPromo, rentalPromoStatus, validateRentalPromo } from '../../../common/utils/rentalPromoCore';

const DAYS = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];
const hourLabel = minute => {
  if (minute === 1440) return '12:00 a.m. (midnight, end of day)';
  const hour = minute / 60;
  return `${hour % 12 || 12}:00 ${hour < 12 ? 'a.m.' : 'p.m.'}`;
};
const money = amount => `₱${amount.toLocaleString('en-PH', { maximumFractionDigits: 2 })}`;
const inputClass = 'mt-1 block w-full rounded border border-slate-200 p-2';

export default function RentalPromoSettings({ value, onChange, disabled = false, now }) {
  const promo = resolveRentalPromo(value);
  const error = validateRentalPromo(promo);
  const status = rentalPromoStatus(promo, now);
  const update = patch => onChange({ ...promo, ...patch });
  const total = hours => Math.floor(hours / 2) * promo.blockPrice + (hours % 2) * promo.singleHourPrice;
  const selectedDays = DAYS.filter((_, day) => promo.weekdays.includes(day)).join(', ');
  const hasMatchingDate = !error && promo.startDate && Array.from({ length: 7 }, (_, offset) => {
    const date = new Date(`${promo.startDate}T00:00:00Z`);
    date.setUTCDate(date.getUTCDate() + offset);
    return date.toISOString().slice(0, 10) <= promo.endDate && promo.weekdays.includes(date.getUTCDay());
  }).some(Boolean);

  return (
    <fieldset disabled={disabled} className="mt-4 rounded-lg border border-slate-200 p-3 space-y-3 text-xs">
      <legend className="px-1 font-semibold">Temporary court rental promo</legend>
      <label className="flex items-center gap-2">
        <input type="checkbox" checked={promo.enabled} onChange={e => update({ enabled: e.target.checked })} />
        Enable promo
      </label>
      <p className="text-slate-500">Choose play dates, days and hours. Enabled promos apply immediately to qualifying advance bookings, even before the start date.</p>
      <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
        {[['startDate', 'Start date'], ['endDate', 'End date']].map(([key, label]) => (
          <label key={key}>{label}
            <input type="date" className={inputClass} value={promo[key] || ''}
              onChange={e => update({ [key]: e.target.value || null })} />
          </label>
        ))}
      </div>
      <p className="text-slate-500">Both dates are included. For a single day, set the same start and end date. All dates and times use Asia/Manila.</p>
      <fieldset>
        <legend className="mb-2 font-medium">Eligible weekdays</legend>
        <div className="flex flex-wrap gap-x-4 gap-y-2">
          {DAYS.map((day, index) => (
            <label key={day} className="flex items-center gap-1">
              <input type="checkbox" checked={promo.weekdays.includes(index)}
                onChange={e => update({ weekdays: e.target.checked
                  ? [...promo.weekdays, index].sort((a, b) => a - b)
                  : promo.weekdays.filter(value => value !== index) })} />
              {day}
            </label>
          ))}
        </div>
      </fieldset>
      <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
        {[['startMinute', 'Promo start time', 0], ['endMinute', 'Promo end time', 1]].map(([key, label, offset]) => (
          <label key={key}>{label}
            <select className={inputClass} value={promo[key]} onChange={e => update({ [key]: Number(e.target.value) })}>
              {Array.from({ length: 24 }, (_, index) => (index + offset) * 60).map(minute => (
                <option key={minute} value={minute}>{hourLabel(minute)}</option>
              ))}
            </select>
          </label>
        ))}
      </div>
      <p className="text-slate-500">Whole hours only. End time must be later on the same day. Only bookable court hours can receive the promo.</p>
      <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
        {[['singleHourPrice', 'Single court-hour price (PHP)'], ['blockPrice', 'Two court-hour package price (PHP)']].map(([key, label]) => (
          <label key={key}>{label}
            <input type="number" min="0" step="0.01" className={inputClass} value={promo[key] ?? ''}
              onChange={e => update({ [key]: e.target.value === '' ? '' : Number(e.target.value) })} />
          </label>
        ))}
      </div>
      <p className="text-slate-500">The package must cost at least one single court-hour and no more than two. For a flat hourly rate, set the package to twice the single court-hour price.</p>
      <label className="block">Bookings crossing the promo time window
        <select className={inputClass} value={promo.application} onChange={e => update({ application: e.target.value })}>
          <option value="eligible-hours">Promo for eligible hours; remaining hours at normal rates</option>
          <option value="whole-period">Entire continuous period must be inside the promo window</option>
        </select>
      </label>
      {error && <p role="alert" className="text-rose-600">{error}</p>}
      {!error && promo.startDate && !hasMatchingDate && <p role="alert" className="text-amber-700">No dates in this range match the selected weekdays. Choose a matching weekday or extend the date range.</p>}
      <div role="status" aria-live="polite" className="rounded-lg bg-slate-50 p-3 space-y-2">
        <p className="font-semibold">Draft promo preview</p>
        <p>Status: {error ? 'incomplete' : status}.</p>
        {!error && <>
          <p>{promo.startDate} to {promo.endDate} · {selectedDays} · {hourLabel(promo.startMinute)}–{hourLabel(promo.endMinute)}</p>
          <ul className="grid grid-cols-2 gap-2 sm:grid-cols-4" aria-label="Cumulative court-hour prices">
            {[1, 2, 3, 4].map(hours => <li key={hours}>{hours} court-hour{hours > 1 ? 's' : ''}: <strong>{money(total(hours))}</strong></li>)}
          </ul>
          <p>Totals combine eligible court-hours across all courts in one booking. Two courts × 1 hour = {money(total(2))}; two courts × 2 hours = {money(total(4))}.</p>
          {status === 'scheduled' && <p>Future play dates are scheduled. Qualifying advance bookings receive this promo as soon as you enable and save it.</p>}
          {status === 'disabled' && <p>Disabled promos do not apply to new bookings.</p>}
          {status === 'expired' && <p>The last eligible play date has passed.</p>}
        </>}
      </div>
      <p className="text-slate-500">Changes take effect after Apply and Save. Existing saved bookings keep their prices.</p>
    </fieldset>
  );
}
